  [858376326119168] = "Desempenho de truque",
  [858376326118144] = "Reaparecimento da pegada",
  [858376326115584] = "Reino dos Mistérios",
  [858376326114560] = "Espiritualidade Explosão",
  [858376326114048] = "Enganando o Destino",
  [858376326113024] = "Substituto de estatueta de papel",
  [858376326111488] = "Bênção do tolo",
  [858376326110976] = "Mestre de cartas",
  [1090717413804032] = "Pacificar",
  [858376326109440] = "Matriz de Tarô",
  [858376326104832] = "Psicoterapia",
  [858376326103808] = "Invisibilidade Psicológica",
  [858376326103296] = "Leitura da Mente",
  [858376326102784] = "Manipulação da Consciência",
  [858376326102272] = "Frenesi",
  [858376326101760] = "Sugestão Psicológica",
  [858376326101248] = "Tecelagem de Sonhos",
  [858376326100736] = "Orientação Mental",
  [858376326100224] = "Dissuasão",
  [858376326099200] = "Praga Mental",
  [858376326098688] = "Entendimento",
  [285943353412352] = "Aproveite a percepção básica de informações concedida pelo Espreitador de Mistérios Sequência, puxando os fracos fluxos de informações que flutuam ao seu redor para condensar uma Nota Secreta coberta com padrões de luz fracos. \n Aumenta seu conhecimento em 1.",
  [858376326094080] = "Armadura Sagrada",
  [285943353411584] = "Cada Ataque Básico tem 5% <HighLight></> de chance, e cada habilidade de combate tem 15% <HighLight></> de chance de disparar um Vórtice de Conhecimento na direção que você está enfrentando, causando *d de dano mágico aos inimigos ao longo do caminho e aplicando Redução de Cura <HyperLink stylename=\"M_Link\" u=\"20\"></> por *f segundos calculados como mul(*d**,*d). \n Se um Vórtice de Conhecimento não for acionado após um Ataque Básico ou habilidade, a probabilidade se acumula.",
  [285943890213632] = "Dispense o reino e restaure a saúde instantaneamente.",
  [285943890282496] = "O poder místico transborda durante o combate, interferindo nos inimigos. Liberar ataques ou habilidades básicas tem a chance de ativar um Vórtice de Conhecimento adicional, causando dano e Redução de Cura.",
  [285943890281984] = "Causa dano de área e reduz o dano sofrido pelo usuário.",
  [285942816443904] = "Modelo 9",
  [285943353402368] = "Desperte a afinidade natural com corpo a corpo armas dentro da linhagem do Gigante do Crepúsculo, mesclando as habilidades refinadas do Mestre de Armas com espadas grandes e espadas duplas. Usando força bruta extraordinária como guia, condense a forma física da arma correspondente. \n Aumenta sua intuição em 4 e sua potência em 2.",
  [285943353344256] = "Nesta postura, o dano causado é significativamente reduzido, mas sua capacidade de cura é aprimorada e os atributos ofensivos podem aumentar a quantidade de cura (o aumento depende do tipo de atributo e do multiplicador de habilidade). \n Nesta postura, quando você é afetado por <HyperLink stylename=\"M_Link\" u=\"3\"> Crowd Control </> , você ganha buffdisc(*id) por passivadisc(*id) segundos; este efeito tem um recarga interno de 15 segundos.",
  [285943890294272] = "Restaura o valor SAN em uma área, aumenta o Conhecimento, Artes Marciais, Carisma e Intuição e adiciona <HighLight> Dragon's Physique </> e <HighLight> Dragon's Fury </> . <HighLight> (Somente lançado no chão) </>",
  [285943890284288] = "Invoque seu Espreitador de Mistérios espiritualidade para conduzir um Ritual de Mistério exclusivo, acompanhado por um conjunto de movimentos rituais de bruxo complexos e padrão e um círculo mágico materializado. O processo é completo e cheio de talento ritualístico, representando o refinamento máximo do fluxo e da forma do Ritual de Mistério, adequando-se à característica do mago de \"Enfatizar o ritual e estudar princípios secretos\".",
  [285943890283520] = "Com base na análise precisa e no estudo de técnicas de combate do Fighting Scholar, você atinge instantaneamente uma postura de combate padrão e definitiva. Depois de manter a postura por alguns segundos, você retorna naturalmente ao seu estado normal. A trajetória técnica refinada da postura permanece ao seu redor, fazendo com que seu próximo ataque manifeste uma pós-imagem de combate, aderindo à característica central do Fighting Scholar: \"Usar a essência do mistério para moldar o ímpeto do combate.\"",
  [285943890283264] = "Use seu Mystery Pryer espiritualidade para condensar uma Nota Secreta. Quando desdobrado, um segredo diário trivial aparece nele, revelando fragmentos de verdade esquecidos nos arredores. A nota se dissipa com seu espiritualidade após ser lida; é uma habilidade introdutória para um Espreitador de Mistérios tocar a essência do \"Oculto\".",
  [633321382017024] = "Registro",
  [633321381989120] = "Gambito das Eras",
  [285943890280960] = "Use o poder do vasto conhecimento para criar uma Torrente de Informações que ataca continuamente os inimigos, consumindo conhecimento místico para causar grandes danos ao longo do tempo.",
  [285943890280704] = "Transforme-se em luz estelar, remova todos os efeitos de controle de você mesmo e ganhe Super Armadura, Redução de Dano e Aumento de Velocidade de Movimento.",
  [285943890280448] = "Realize magia de conto de fadas para desdobrar o Gambito das Eras, acelerando seu próprio fluxo de tempo e ganhando superarmadura. Após um breve atraso, causa dano de área e arremesso, enquanto reduz o tempo de recarga de suas próprias habilidades. Ganhe conhecimento misterioso (usado para desbloquear habilidades de finalização) após o lançamento.",
  [285943890279168] = "Extraia o poder do conhecimento para invocar uma ilusão misteriosa invencível ao lado do alvo, causando dano contínuo aos inimigos. A segunda etapa permite trocar de posição com a ilusão. Ganhe conhecimento misterioso (usado para desbloquear habilidades de finalização) após o lançamento.",
  [285943890278656] = "Abra os Olhos do Mistério Inquisitivo para ver através das ilusões, causando dano de área centrado em você e repelindo inimigos, removendo escudos inimigos e aplicando redução de cura. O segundo estágio permite um rápido deslocamento para trás. Ganhe conhecimento misterioso (usado para desbloquear habilidades de finalização) após o lançamento.",
  [285943890278400] = "Realize magia de conto de fadas, usando poderes misteriosos para se proteger, ganhando um escudo, super armadura e conhecimento misterioso (usado para desbloquear habilidades de finalização).",
  [285943890277888] = "Condense uma gaiola com luz estelar para causar dano e atordoar o alvo, ganhando conhecimento misterioso (usado para desbloquear habilidades de finalização). Pode ser fortalecido pela habilidade Knowledge Pursuit, transformando o controle em controle de área.",
  [285943890277632] = "Invoque uma Starlight Cage para causar dano e atordoar o alvo, ganhando conhecimento misterioso (usado para desbloquear habilidades de finalização). Pode ser fortalecido pela habilidade Knowledge Pursuit, transformando o controle em controle de área.",
  [285943890277120] = "Solte Star Sand na área alvo para dissolvê-lo, causando dano de área e ganhando conhecimento misterioso (usado para desbloquear habilidades de finalização). Pode ser fortalecido pela habilidade Knowledge Pursuit, causando dano contínuo adicional, lentidão e arremesso.",
  [285943890275584] = "Excite o brilho para refratar entre os inimigos, causando dano e estagnação enquanto ganha conhecimento misterioso (usado para desbloquear habilidades de finalização). Pode ser fortalecido pela habilidade Knowledge Pursuit, aumentando o dano e adicionando redução de lentidão e ataque.",
  [285943890275328] = "Solte um pergaminho para causar dano aos inimigos e ganhar infusão de conhecimento, fortalecendo seu próximo ataque normal e as próximas duas habilidades de combate que podem ser fortalecidas. Ganhe conhecimento misterioso (usado para desbloquear habilidades de finalização) após o lançamento.",
  [285943890275072] = "Condense a Lança de Longinus para descer do céu, realizando três golpes nos inimigos em uma pequena área, ganhando conhecimento misterioso (usado para desbloquear habilidades de finalização) e aplicando redução de cura.",
  [285943890273536] = "Execute bruxaria para atacar o alvo e obter conhecimento misterioso (usado para desbloquear habilidades de finalização). Depois de liberar Knowledge Pursuit, ele é fortalecido na Lança de Longinus, aumentando o dano e o misterioso ganho de conhecimento, ao mesmo tempo que adiciona redução de cura.",
  [285943890273280] = "Canalize o poder de sintonização de armas do Gigante do Crepúsculo, combinado com a técnica de controle de armas completas do Mestre de Armas, para invocar aleatoriamente a forma física de uma espada grande ou de espadas duplas. Execute a postura robusta específica para armas; embora não tenha efeito de ataque real, serve para manifestar o controle de 'homem e arma como um só', alinhando-se com a característica do Mestre de Armas 'todas as armas são para meu uso'.",
  [285943890272512] = "Canalize o poder da linhagem do Gigante do Crepúsculo para condensar uma postura de batalha, vinculando a trajetória de seu poder à sua postura de ataque, fazendo com que uma sombra fantasma de ataque pesado idêntica ao seu corpo principal apareça simultaneamente durante seu próximo ataque.",
  [285943890272256] = "Canalize o escasso poder da linhagem gigante para sua perna esquerda, levante o pé e pise no chão com força, provocando um leve tremor no solo ao redor e levantando poeira. Esta é uma habilidade básica para um Guerreiro alavancar sua força gigante, alinhando-se com a característica 'A Força Funde-se na Terra'.",
  [285943890270976] = "Como um Mestre de Armas natural, o Guerreiro pode usar habilmente uma variedade de armas. Use espadas duplas na Postura Ofensiva para aumentar seu dano; use uma espada grande em Forma de Defesa para obter redução de dano e atrair monstros mais facilmente ameaça.",
  [285943890270208] = "Transforme-se em um gigante para obter invencibilidade breve e dissipar efeitos negativos, depois execute ataques contínuos com lentidão enquanto se move. Ganhe super armadura e redução de dano durante esse período.",
  [285943890269696] = "Interrompa os inimigos com uma ofensiva contínua e incessante, causando dano em vários estágios, depois condense espiritualidade em uma entidade gigante para lançar um finalizador, causando dano extra aos inimigos deteriorados. Ganhe 4 Dusk Marks (usadas para fortalecer Angry Slam e habilidades de finalização) após o lançamento.",
  [285943890269184] = "Condense espiritualidade em uma entidade gigante para lançar um golpe final em conjunto, causando dano massivo enquanto aplica redução de cura aos jogadores inimigos. Ganhe 4 Dusk Marks (usadas para fortalecer Angry Slam e habilidades de finalização) após o lançamento.",
  [285943890268672] = "Invoca uma projeção gigante que bate no chão, causando dano de área.",
  [285943890268160] = "Dissipe o mal, remova todos os efeitos de controle, entre no estado de super armadura e ganhe redução de dano e efeitos de aceleração enquanto restaura a saúde.",
  [285943890267136] = "Solte uma formação de espada no local alvo; a formação de espada causa dano aos inimigos. Aplica deterioração (dano contínuo) na Postura Ofensiva.",
  [285943890266112] = "Empunhe espadas duplas para lançar uma ofensiva semelhante a uma tempestade, causando danos massivos e controlando os inimigos com golpes contínuos. Você ganha uma Dusk Mark (usada para fortalecer o Angry Slam e as habilidades de finalização). Aplica deterioração (dano contínuo) na Postura Ofensiva.",
  [285943353357056] = "Limpe-se de <HyperLink stylename=\"M_Link\" u=\"3\"> efeitos de controle </> , ganhe <HighLight> 0,5 </> segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> e <HighLight> 4 </> segundos de 15% <HighLight> Redução de Dano </> , coloque um farol de chama em sua posição atual e, em seguida, pisque para o local alvo. Cause *d dano físico em uma pequena área ao redor do ponto de desaparecimento e do local alvo.",
  [285943890263296] = "Exerça uma esgrima requintada, atingindo os inimigos com diferentes técnicas de espada cada vez que for lançada. Pode ser carregado para liberar técnicas de espada combinadas contínuas. Fortalecido quando você tem uma Marca do Crepúsculo.",
  [285943890262528] = "Crave a espada grande no chão para desintegrar a realidade ao seu redor, mantendo a super armadura enquanto carrega para causar dano aos inimigos ao redor. Após carregar, lança um finalizador que causa dano massivo e detona decadência; quanto maior a duração restante, maior será o dano. Fortalecido quando você tem uma Marca do Crepúsculo.",
  [285943890262016] = "Crave a espada grande no chão para desintegrar a realidade ao seu redor, ganhando super armadura contínua. Causa dano de área ao seu redor com base em sua saúde máxima e fornece um escudo de alto valor e redução de dano a aliados com pouca saúde. Fortalecido quando você tem uma Marca do Crepúsculo.",
  [285943890261248] = "Crave a espada grande no chão para desintegrar a realidade ao seu redor, ganhando super armadura contínua. Causa dano de área ao seu redor com base em sua saúde máxima e fornece um escudo aos aliados próximos. Fortalecido quando você tem uma Marca do Crepúsculo.",
  [285943890260736] = "Condense um florete prateado com espiritualidade para lançar um ataque surpresa, ganhando uma Marca do Crepúsculo (usada para fortalecer o Angry Slam e as habilidades de finalização). O poder de ataque é fortalecido e você executa um ataque de perseguição para causar dano extra.",
  [285943890260480] = "Condense a armadura com espiritualidade para cobrir seu corpo, ganhando um escudo que absorve dano e uma Marca do Crepúsculo (usada para fortalecer Angry Slam e habilidades de finalização). Ganhe super armadura contínua quando o escudo for quebrado. Carregar esta habilidade garante alta redução de dano com pouca saúde.",
  [285943890260224] = "Condense a armadura com espiritualidade para cobrir seu corpo, ganhando um escudo que absorve dano e uma Marca do Crepúsculo (usada para fortalecer Angry Slam e habilidades de finalização). Ganhe super armadura contínua quando o escudo for quebrado. Carregar esta habilidade concede defesa e redução de dano com pouca saúde.",
  [285943890259968] = "Segure uma espada larga e gire como um furacão, causando continuamente dano de área. Você ganha continuamente Dusk Marks (usadas para fortalecer Angry Slam e habilidades de finalização), arrasta monstros e retarda jogadores. A Forma de Defesa pode provocar monstros.",
  [285943890259200] = "Segure uma espada larga e gire como um furacão, causando continuamente dano de área. Você ganha continuamente Dusk Marks (usadas para fortalecer Angry Slam e habilidades de finalização), arrasta monstros e retarda jogadores inimigos. A Forma de Defesa pode provocar monstros.",
  [285943890258688] = "Lance um ataque de escudo de carga contra os inimigos e, em seguida, use o impulso para saltar, aplicando decadência (dano contínuo) aos inimigos enquanto causa dano e controle. Aplica redução de cura adicional aos jogadores inimigos, dissipa o controle de grupo suave e adiciona redução de dano aos jogadores aliados, e você ganha uma Marca do Crepúsculo (usada para fortalecer o Angry Slam e as habilidades de finalização). Desbloqueia o Royal Court Command após o uso.",
  [285943890258432] = "Fornece carga de suporte aos aliados, dissipando seu controle de multidão suave e lento, e fornecendo-lhes redução de dano e buffs de aceleração. Você ganha uma Dusk Mark (usada para fortalecer o Angry Slam e as habilidades de finalização). Desbloqueia o Royal Court Command após o uso.",
  [285943890257664] = "Lance um ataque de escudo de carga contra os inimigos e, em seguida, use o impulso para saltar, aplicando decadência (dano contínuo) aos inimigos enquanto causa dano e controle. Aplica redução de cura adicional aos jogadores e você ganha uma Marca do Crepúsculo (usada para fortalecer o Angry Slam e as habilidades de finalização). Desbloqueia o Royal Court Command após o uso.",
  [285943890256640] = "Condense a energia da espada com espiritualidade para puxar os inimigos em sua direção e aplicar estagnação, depois execute um salto com força total para frente para causar dano. Você ganha uma Dusk Mark (usada para fortalecer Angry Slam e habilidades de finalização) e aplica prisão e redução de cura aos jogadores. A Forma de Defesa pode provocar monstros.",
  [285943890255616] = "Gire espadas duplas para executar técnicas de espada contínuas, rápidas e semelhantes ao vento na frente, aplicando decadência (dano contínuo) aos inimigos enquanto ganha uma Marca do Crepúsculo (usada para fortalecer Angry Slam e habilidades de finalização).",
  [285943890254848] = "Empunhe uma espada larga para golpear à esquerda e à direita com força estrondosa e, em seguida, execute um poderoso golpe para baixo na frente, causando dano e ganhando uma Marca do Crepúsculo (usada para fortalecer o Angry Slam e as habilidades de finalização).",
  [285943890254080] = "Gerar uma Porta do Viajante; você e seus companheiros de equipe podem se teletransportar pela Porta do Viajante, com uma distância máxima de teletransporte de 30 metros.",
  [285943890252544] = "Abra uma caixa de truques feita especialmente para Aprendizes, usando o controle básico sobre o espaço e o traço elementar espiritualidade para emitir um flash de luz ofuscante enquanto tira uma foto.",
  [285943890252288] = "Baseando-se no espaço básico espiritualidade concedido pelo Aprendiz Sequência , perceba âncoras espaciais para abrir um portal para o desconhecido, permitindo que o Aprendiz o atravesse. \n Através da percepção básica de 'desconstrução e reconstrução espacial' ao abrir a porta, manifesta-se o contato inicial do Aprendiz com as regras espaciais.",
  [285943890252032] = "Quando um Aprendiz lança habilidades de combate, ele acumula energia estelar e pegadas. A energia Starlight é usada para desbloquear e fortalecer as habilidades de finalização do Aprendiz, enquanto as pegadas são usadas para fortalecer os ataques normais do Aprendiz.",
  [285943890251520] = "Evoca uma Starlight Cage para atacar alvos dentro do alcance, causando aprisionamento e lentidão, com atordoamento adicional no alvo travado.",
  [285943890251008] = "Detenha os inimigos com um rugido estrondoso e, em seguida, convoque uma projeção gigante para bater no chão, causando dano de área e lentidão.",
  [285943890248960] = "Use truques aleatórios para atacar inimigos no local alvo, aplicando efeitos adicionais com base no tipo de truque.",
  [285943890248448] = "Invoque o poder astral para se movimentar e causar dano aos inimigos à frente, aplicando redução de cura.",
  [285943890247936] = "Dispare continuamente múltiplas balas de ar contra os inimigos.",
  [285943890246656] = "Condense três eixos curtos do brilho que explode de dentro; os eixos orbitam você, atingindo continuamente os inimigos ao redor e causando dano e lentidão.",
  [285943890245632] = "Pode ser lançado quando a energia da luz das estrelas for de pelo menos 3 pontos. Consome toda a energia da luz das estrelas para primeiro lançar um golpe nos inimigos, depois convoca várias sombras fantasmas para atacá-los, finalmente detonando a energia da luz das estrelas para causar danos massivos. Quanto mais energia da luz das estrelas for consumida, maior será o dano.",
  [285943890241024] = "Convoca estrelas para caírem sobre os inimigos, causando danos massivos aos inimigos na área alvo.",
  [285943890240512] = "Fuja para o Mundo Espiritual para vagar, dissipando imediatamente os efeitos de controle sobre você e ganhando super armadura, maior velocidade de movimento e redução de danos. Causa dano e lentidão aos inimigos ao redor, então você pode acionar um combo para lançar um ataque surpresa, causando dano, lentidão e arremesso.",
  [285943890240256] = "Registre a habilidade Beyonder de um alvo Caminho . Depois que a habilidade for liberada, você pode acionar um combo para invocar uma projeção que usa a habilidade Beyonder gravada.",
  [285943890239232] = "Crie uma Jaula Espacial para coordenar ataques aos inimigos dentro da jaula, causando dano contínuo e ao mesmo tempo fornecendo super armadura e redução de dano. A gaiola então desmorona, causando dano adicional aos inimigos. Space Cage concede o efeito Study, fortalecendo certas habilidades de combate.",
  [285943890237952] = "Use o poder para apagar espaço, causando dano contínuo aos inimigos dentro do alcance, seguido por um finalizador que causa dano massivo. Causa efeitos adicionais de coleta e arremesso aos monstros.",
  [285943890237696] = "Invoque o poder astral para se movimentar e causar dano aos inimigos à frente, aplicando redução de cura. Depois de liberar Space Cage, os efeitos desta habilidade são fortalecidos e você ganha energia de luz estelar adicional.",
  [285943890236928] = "Condense a luz das estrelas para atacar os inimigos, causando dano e atordoamento. Após o lançamento, você pode acionar um combo para retornar à posição inicial.",
  [285943890236672] = "Em um instante, atravesse o espaço para se teletransportar na direção oposta, causando dano e estagnação aos inimigos ao longo do caminho. Pode ser cobrado duas vezes.",
  [285943890236160] = "Transforme-se em uma sombra fantasma para avançar em direção à área alvo, ganhando breve invencibilidade e super armadura, depois detone a área alvo para causar dano e aplicar redução de cura.",
  [285943890235648] = "Use truques aleatórios para atacar inimigos no local alvo, aplicando efeitos adicionais com base no tipo de truque. Depois de liberar Space Cage, os efeitos desta habilidade são fortalecidos e você ganha energia de luz estelar adicional.",
  [285943890232832] = "Reúna a energia da luz das estrelas para lançar até quatro ataques. Coletar pegadas permite o Reaparecimento de Pegadas, que fortalece Flash Strike, reduz o tempo de recarga de suas habilidades e aplica uma chance de lançar inimigos no ar e retardá-los.",
  [285943890228480] = "Invoca uma projeção histórica do Reino dos Mistérios para manipular os corpo espiritual fios de todos os inimigos, puxando-os em direção ao centro enquanto causa dano contínuo, seguido por um finalizador que causa dano massivo e arremesso. Você ganha uma carta idêntica à obtida anteriormente (usada para desbloquear habilidades de finalização), juntamente com os efeitos adicionais correspondentes.",
  [285943890227712] = "Baseando-se nas estatuetas de papel preparadas pelo Mago e pelos Sequência 's espiritualidade , transforme o corpo físico em um Substituto da Estatueta de Papel quando as condições predefinidas forem atendidas, fazendo com que ele se dissipe gradualmente e permitindo uma saída sem rastros. Essencialmente uma 'abertura de cortina perfeita' pré-planejada, isso se alinha com o princípio fundamental de que 'um mágico nunca atua sem preparação', usado para evitar o perigo ou completar um ciclo de atuação.",
  [285943890227200] = "Utilizando a coordenação física e o controle facial do Palhaço Caminho, execute um ato contraditório de 'riso mascarando a tristeza'. Através de movimentos físicos exagerados e cômicos e de um forte contraste entre o absurdo superficial e a desolação interior, você se alinha com a característica central do Sequência: 'desamparo do destino enquanto é forçado a rir.'",
  [285943890225664] = "Baseando-se na conexão secreta entre o corpo astral, o Mundo Espiritual e o céu estrelado, use um pêndulo feito de cristal, pedra preciosa ou metal especial como meio para perceber a fortuna e as tendências de um alvo. \n A direção e a velocidade de rotação do pêndulo correspondem a diferentes níveis de orientação: \n ▸ Balanço rápido no sentido horário: Afirmação forte / Tendência favorável \n ▸ Balanço lento no sentido horário: Afirmação fraca / Tendência suave \n ▸ Balanço rápido no sentido anti-horário: Negação forte / Risco de estagnação \n ▸ Balanço lento no sentido anti-horário: Negação fraca / Obstáculo potencial \n ▸ Estacionário: Nenhuma revelação clara ou interferência presente",
  [285943890225408] = "Manipule o destino e espiritualidade , manifestando-os na forma de cartas para enganar os inimigos. Colete Fate Yellow Cards e Espiritualidade Blue Cards para desbloquear as habilidades de finalização Fooling of Fate e Espiritualidade Burst, e colete a energia das cartas para desbloquear a habilidade de finalização Shuffle Cards.",
  [285943890224640] = "Invoque uma projeção histórica do Reino dos Mistérios para manipular os corpo espiritual fios dos inimigos alvo. Isso retarda e estagna os inimigos dentro do alcance, causando dano contínuo, seguido por um finalizador que causa dano massivo e arremesso em alvos monstros ou atordoa os alvos dos jogadores. Você ganha uma carta idêntica à obtida anteriormente (usada para desbloquear habilidades de finalização).",
  [285943890223360] = "Colete Card Energy para desbloquear a habilidade. Injete toda a energia das cartas coletada em um grande número de cartas, despejando continuamente cartas cheias de energia nos inimigos para causar grandes danos. Outras habilidades podem ser liberadas e o movimento é possível durante o processo de fundição.",
  [285943890223104] = "Colete Espiritualidade Cartões Azuis para desbloquear a habilidade. Libera o poder espiritual do usuário, causando dano massivo aos inimigos dentro do alcance e aplicando Vulnerabilidade. Usá-lo concede um ponto de Energia da Carta.",
  [285943890222848] = "Colete Cartões Amarelos do Destino para desbloquear a habilidade. Engane os inimigos dentro do alcance, causando dano massivo. Depois disso, por um período de tempo, os ataques normais do usuário aplicarão uma Marca de Enganação que causa dano adicional e a velocidade de ataque aumentará. Usá-lo concede um ponto de Energia da Carta.",
  [285943890221824] = "Remova os efeitos de controle, deixe para trás um Substituto de Estatueta de Papel para confundir os inimigos e desloque-se para o local alvo.",
  [285943890221312] = "Evoca milagrosamente uma chuva de cartas no local alvo, causando dano, lentidão e atordoamento aos inimigos, além de redução de cura adicional aos jogadores. O usuário obtém uma carta idêntica com base no tipo da carta anterior obtida (usada para desbloquear habilidades de finalização) e o efeito adicional correspondente.",
  [285943890220544] = "Acende um farol de fogo preparado, remove os efeitos de controle recebidos, ganha Super Armadura e Redução de Dano e dispara para o local designado, causando dano de área. Usá-lo novamente em 3 segundos permite retornar à posição original.",
  [285943890220288] = "Elogie o Louco, aumentando o dano do usuário por 10 segundos, e obtenha um Espiritualidade Cartão Azul e um ponto de Energia de Cartão (usado para desbloquear Habilidades de Finalização).",
  [285943890220032] = "Pegue emprestado o poder da história, preenchendo imediatamente a Energia da Carta do usuário, e obtenha cartas com base nas cartas atualmente possuídas (usadas para desbloquear Habilidades de Finalização).",
  [285943890219776] = "Manipule os corpo espiritual fios do inimigo, controlando-o e causando dano e Lentidão.",
  [285943890219264] = "Mantenha o movimento e atire continuamente múltiplas balas aéreas contra os inimigos; o usuário ganha um Espiritualidade Blue Card e um ponto de Card Energy (usado para desbloquear Finisher Skills).",
  [285943890218752] = "Jogue uma carta de Tarot no inimigo, desdobrando um Tarot Array para causar dano continuamente e derrubar alvos monstros ao terminar. O usuário obtém uma carta idêntica com base no tipo da carta anterior obtida (usada para desbloquear habilidades de finalização) e o efeito adicional correspondente.",
  [285943890217984] = "Jogue rapidamente várias cartas de baralho para frente para causar dano de área; a habilidade tem três estágios. Na primeira etapa, o usuário ganha um efeito piercing; no terceiro estágio, os inimigos são repelidos, sofrem Redução de Cura e são aplicados com uma Marca de Fooling para causar dano adicional, enquanto o usuário ganha um Cartão Amarelo do Destino (usado para desbloquear Habilidades de Finalização).",
  [285943890216960] = "Lance cartas de baralho para atacar o alvo. Após esta habilidade causar dano 4 vezes, obtenha uma carta idêntica com base no tipo da carta obtida anteriormente (usada para desbloquear habilidades de finalização).",
  [285943890216704] = "Use sugestões enganosas em um único alvo de jogador inimigo, causando Perturbação Mental.",
  [285943890216448] = "Invoque a observação da mente espiritualidade do Espectador Sequência para realizar Psicoterapia, convertendo aleatoriamente as emoções negativas/neutras do alvo em emoções positivas. A nova emoção será apresentada como uma cor correspondente dano contínuo e durará um período de tempo. Esta é a habilidade central do Psicólogo: 'Usar o poder de observar emoções para conduzir orientação emocional'.",
  [285943890216192] = "Invoque a observação mental avançada espiritualidade do Espectador Sequência para ler os pensamentos superficiais concretos de um alvo cujo espectro emocional foi identificado. Este é o avanço central do 'Reconhecimento Emocional' para a 'Leitura da Mente', adequando-se à característica do Leitor de Mente: 'Observe as emoções e alcance o coração, sondando a camada superficial'.",
  [285943890215936] = "Invoque a percepção emocional básica do Espectador Sequência, condensando uma cor dano contínuo ao redor do alvo correspondente ao seu humor central do dia, apresentando visualmente o estado emocional com cores: \n ▸ Vermelho para Paixão \n ▸ Amarelo para Paz \n ▸ Branco para Neutro \n ▸ Cinza para Melancolia \n ▸ Preto para Tristeza.",
  [285943890215424] = "Uma Postura de Pesadelo especializada em combate. Ao usar habilidades de combate para causar dano, o usuário se cura, mas a cura aplicada pelo usuário é significativamente reduzida.",
  [285943890215168] = "Uma Postura de Imaginação especializada em cura. Quando controlado, o usuário restaura a saúde, mas o dano causado é significativamente reduzido.",
  [285943890214912] = "Desperte do sonho e restaure 50% da saúde.",
  [285943890214400] = "Desperte um companheiro de equipe dissipado do sonho e restaure 50% de sua saúde.",
  [634144941950976] = "Espingarda",
  [285943890213376] = "Fuja para o Oceano Subconsciente, remova os efeitos de controle de si mesmo e convoque um dragão gigante para circular a área alvo, fornecendo efeitos de recuperação aos aliados dentro do alcance.",
  [285943890212608] = "Fornece psicoterapia continuamente aos aliados próximos, restaurando sua saúde.",
  [285943890211840] = "Libere Mind Fire para irromper e deixar um campo de fogo, causando dano de área, Redução de Cura e Aprisionamento, e hipnotizando o alvo.",
  [285943890211584] = "Torne-se difícil de ser detectado pelos inimigos, remova os efeitos de controle recebidos, entre no estado de Super Armadura, ganhe Redução de Dano, aumento de cura recebida e aceleração.",
  [285943890211328] = "Reduza a defesa do inimigo alvo e cause dano a ele.",
  [285943890210816] = "Analise e proteja as mentes de todos os companheiros de equipe por um curto período de tempo, proporcionando cura adicional massiva e redução de danos.",
  [285943890210560] = "Leia, analise e proteja continuamente a mente do alvo, fornecendo cura adicional e um escudo quando a saúde estiver baixa.",
  [285943890209792] = "Fornece continuamente sugestões positivas ao subconsciente de si mesmo e de seus companheiros de equipe, ganhando Redução de Dano, Super Armadura e cura contínua para aliados próximos.",
  [285943890209280] = "Lance um feroz Mind Shock para frente, causando dano massivo, Lentidão e Redução de Cura.",
  [285943890209024] = "Fornece sugestão psicológica positiva ao alvo, restaurando imediatamente uma grande quantidade de saúde ao alvo e proporcionando um efeito de redução de danos de curto prazo.",
  [285943890208256] = "Crie um reino onírico caótico na área alvo, causando dano contínuo aos inimigos dentro do reino.",
  [285943890208000] = "Guie a energia mental calma e serena para passar entre os companheiros de equipe, restaurando a saúde dos companheiros por onde passa.",
  [285943890207488] = "Exerça Dragon Might para deter os inimigos dentro do alcance, causando danos massivos e derrubando monstros em estado de praga.",
  [285943890206464] = "Crie um Reino dos Sonhos pacífico, restaurando continuamente a saúde dos aliados dentro do reino e aumentando sua Redução de Dano.",
  [285943890205696] = "Espalhe uma Peste Mental na área alvo, causando dano e infectando unidades inimigas dentro do alcance.",
  [285943890205440] = "Discernir e explorar as vulnerabilidades mentais dos inimigos, causando dano de área e aplicando um estado de Vulnerabilidade.",
  [285943890204672] = "Acalma a mente de um aliado, restaurando uma certa quantidade de saúde ao alvo.",
  [285943890203904] = "Lança um choque de energia mental no inimigo, causando dano a um único alvo.",
  [285943890203392] = "Ganhe um status; ao terminar, cause dano ao ambiente.",
  [285943890203136] = "Conceda aos aliados a habilidade Purificação.",
  [285943890202880] = "Usando a piedade sincera como guia, rompa a fina barreira entre a realidade e o domínio do Sol, convocando um feixe de Luz Sagrada, não contaminado por quaisquer impurezas mundanas, para descer sobre si mesmo.",
  [285943890202624] = "Recite frases curtas de oração relacionadas ao Sol, desenhando um raio de brilho sagrado condensado, mas não abrasador, que pousa precisamente na cabeça do alvo, formando um feixe de luz continuamente flutuante.",
  [285943890202112] = "Cante hinos com frases que se enquadrem no simbolismo da divindade do Deus Sol.",
  [285943890201856] = "Estabeleça os princípios da Justiça para punir os transgressores heréticos do juramento. Quando Punishment e Unshadowed Spear atingirem um inimigo, aplique uma marca de Heresia ao alvo, aumentando o dano recebido do Bardo. No estado Sol Ardente, acertar com habilidades de combate também aplicará uma marca de Heresia ao alvo.",
  [285943890201600] = "Estabelecer os princípios da Justiça e agir em conformidade; os caminhos de aquisição de energia aumentam. Ao executar Punishment e Unshadowed Spear, o usuário acumula Julgamento da Justiça, aumentando o dano de Punishment e Unshadowed Spear. No estado Sol Ardente, lançar habilidades de combate também acumulará Julgamento da Justiça para o usuário. Derrotar, purificar e participar de assistências para derrotar jogadores inimigos concederá Energia Solar.",
  [285943890201088] = "Destrua inimigos fortes com luz branca pura; a luz escaldante atinge como um raio, causando vários golpes no alvo, com cada golpe causando dano crescente.",
  [285943890200576] = "Entre no estado do Sol Ardente; velocidade de movimento e eficiência de aquisição de Energia Solar (usada para desbloquear Punishment e Unshadowed Spear), com duração de 8 segundos. Simultaneamente, o usuário ganha Super Armadura, com duração de 6 segundos. \n O efeito passivo Soul of the Blazing Sun é ativado uma vez a cada 120 segundos: Depois de receber dano fatal, remova os efeitos de controle e ganhe 4 segundos de Invencibilidade, alto aumento de dano e energia solar (usado para desbloquear Punishment e Unshadowed Spear). Durante este período, o recarga da Unshadowed Spear é 0, a cura recebida é reduzida e a saúde é restaurada com base no número de inimigos derrotados.",
  [285943890200064] = "Use a habilidade de Notarização para anular os efeitos de controle recebidos e ganhar buffs, restaurar a saúde e ganhar Super Armadura e Redução de Dano, enquanto causa dano aos inimigos próximos.",
  [285943353356800] = "Use papel espiritual especial para desenhar um modelo carregando sua própria marca espiritual, fazendo com que o corpo físico do alvo siga a orientação do modelo espiritual e se desconstrua em Marionete fragmentos como pedaços de papel, dissipando-se gradualmente com um leve brilho espiritual, enquanto apaga a aura e os traços do alvo em sua posição atual. \nAumenta o Conhecimento do alvo em 4 e a Intuição em 2.",
  [285943890198016] = "Armadura condensada com luz dourada para se proteger, ganhando maior bloqueio e Energia Solar (usada para desbloquear Punição e Lança Sem Sombra). Solte o segundo estágio do combo para remover os efeitos de controle.",
  [285943890197248] = "Envolvido em Chamas Sagradas, ganha Energia Solar (usada para desbloquear Punição e Lança Sem Sombra), purifica inimigos dissipados dentro do alcance e causa dano.",
  [285943890196736] = "Invoque Luz Sagrada para se fortalecer, ganhando uma grande quantidade de Energia Solar (usada para desbloquear Punição e Lança Sem Sombra) e um efeito de Aumento de Dano.",
  [285943890195968] = "Consumir toda a Energia Solar para condensar uma Lança Sem Sombra e jogá-la no inimigo. O dano causado aumenta significativamente com base na Energia Solar consumida e causa dano adicional aos jogadores inimigos com pouca saúde, purificando os jogadores inimigos derrotados. Derrotar um jogador redefine o recarga . \n No estado Sol Ardente, o poder é aumentado e consumirá uma certa porcentagem da saúde atual do usuário para causar dano adicional.",
  [285943890195712] = "Incline-se para frente segurando a alabarda e ataque o inimigo como um raio de luz, derrubando o alvo no chão com o impulso, adicionando Redução de Cura e Estagnação. O usuário ganha Energia Solar (usada para desbloquear Punishment e Unshadowed Spear).",
  [285943890193664] = "Incline-se para frente segurando a alabarda e ataque o inimigo com um impulso imparável, repelindo continuamente o alvo e causando dano. Em seguida, desfere um golpe final com a alabarda para repelir o alvo e causar dano, adicionando Redução de Cura e Estagnação. O usuário ganha Energia Solar (usada para desbloquear Punishment e Unshadowed Spear). A carga irá parar se o alvo tiver Super Armadura.",
  [285943890193408] = "Estabeleça um Juramento Solar no local designado e ganhe Energia Solar (usada para desbloquear Punição e Lança Sem Sombra). Inimigos dentro do alcance do juramento sofrem efeitos de dano, estagnação e aprisionamento.",
  [285943890191872] = "Condense três eixos curtos com o brilho irrompendo de dentro; os machados orbitam o usuário, atingindo continuamente os inimigos ao redor, causando dano, redução de cura e estagnação. O usuário ganha continuamente Energia Solar (usada para desbloquear Punishment e Unshadowed Spear).",
  [285943890191616] = "Levante o joelho para dar um passo à frente, balance a alabarda para atacar, causando dano aos inimigos à frente, purificando os inimigos em um estado dissipado e ganhando Energia Solar (usada para desbloquear Punição e Lança Sem Sombra).",
  [285943890190592] = "Segure a alabarda longa, gire e corte continuamente na frente, depois empurre a alabarda para frente com força para causar dano e ganhar Energia Solar (usada para desbloquear Punição e Lança Sem Sombra). \n No estado Sol Ardente, salte na frente do inimigo e, em seguida, ataque com força total para causar dano e ganhar Energia Solar (usada para desbloquear Punição e Lança Sem Sombra).",
  [285943890189312] = "Transforme-se em uma criatura inofensiva e entre imediatamente em um estado de morte fingida.",
  [285943890189056] = "Permite a montagem durante o combate e causa dano aos alvos colididos.",
  [285943890187776] = "Transforma-se em chamas durante o combate, causando alto dano aos inimigos queimados.",
  [285943890187520] = "Imobilize permanentemente todos os inimigos normais em um raio de 40 metros.",
  [285943890185984] = "Cause múltiplas ocorrências de dano aos inimigos no local alvo.",
  [285943890185728] = "Trave em um alvo; se o alvo estiver a uma distância de 2.000, atire balas nele. Pode ser usado para cancelar o backswing de algumas habilidades.",
  [285943890185472] = "[Modo 3 do controle direito] Uma combinação da habilidade do Modelo 7, usando o eu como centro para causar efeitos em um setor à frente e lançar os inimigos no ar.",
  [285943890185216] = "[Modo do controle direito 3] Use você mesmo como centro para causar efeitos em um setor à frente e libere uma habilidade combinada; entra recarga após a conclusão do combo.",
  [285943890184960] = "[Modo 4 do controle direito] Ataque os inimigos em um retângulo na frente.",
  [285943353354752] = "Utilizando a percepção astral concedida pelo Vidente Sequência, usando um pêndulo contendo espiritualidade natural como uma ponte para construir um canal fraco entre a realidade e o Mundo Espiritual, convertendo símbolos abstratos do Mundo Espiritual em sinais concretos oscilantes. \nAumenta sua intuição em 1.",
  [285943353425408] = "A fenda engole o campo de visão e é também o ponto de partida para governar o mundo. \n \n Mude o céu do cenário mundial atual, com duração de 5 minutos, e convoque a entrada do <HighLight> 'Hall of Fame' </> , com duração de 30 minutos.",
  [285943353425152] = "Montanha de Ferro Magra.",
  [285943353424384] = "Eco do Abismo.",
  [285943353424128] = "Alquimia Resíduos Líquidos.",
  [285943353423360] = "Restaure 100 pontos SAN para aliados em um raio de 30 metros ao redor do usuário, aumente aleatoriamente Erudição, Carisma, Força Marcial ou Intuição e aplique <HighLight> Dragon's Physique </> e <HighLight> Dragon's Fury </> , com duração de <HighLight> 1800 </> segundos. <HighLight> (Somente lançado no chão) </> \n <HighLight> Dragon's Physique </> : Aumenta todas as cinco dimensões em <HighLight> 4 </> pontos; não acumula com os efeitos da Essência Carmesim Avançada. \n <HighLight> Fúria do Dragão </>: Aumenta o Ataque em <HighLight> 25 </> pontos e o Aprimoramento de Habilidade em <HighLight> 5 </> pontos; não acumula com os efeitos da Poção Berserk Avançada.",
  [285943353422848] = "Convocar a Descida do Reino Divino.",
  [285943353422592] = "Liquidação de corações de roda gigante.",
  [285943353422336] = "Acordo de clubes de roda gigante.",
  [285943353422080] = "Liquidação de diamantes da roda gigante.",
  [285943353363456] = "Desfere um golpe nos inimigos ao alcance da frente, causando *d de dano mágico. Ao acertar, consuma todas as <HighLight> Pegadas </> para invocar um remanescente para perseguir (até *d de dano mágico), aplique <HighLight> Queda </> aos inimigos e ganhe <HighLight> Flashback </> . \n <FaintYellow> Cair </> \n faz com que monstros inimigos sejam <HyperLink stylename=\"M_Link\" u=\"2\"> lançados </> . Se mais de 2 pilhas de <HighLight> Pegadas </> forem consumidas, há uma chance base de <HighLight> 42% </> de aplicar, por *f segundos, o efeito de buffdisc(*id). Se 3 pilhas de <HighLight> Pegadas </> forem consumidas, há uma chance básica de <HighLight> 70% </> de <HyperLink stylename=\"M_Link\" u=\"2\"> lançar </> jogadores inimigos. Depois de serem <HyperLink stylename=\"M_Link\" u=\"2\"> lançados </> por esta habilidade, os alvos dos jogadores não podem ser <HyperLink stylename=\"M_Link\" u=\"2\"> lançados </> novamente por esta habilidade por um curto período de tempo. \n <FaintYellow> Flashback </> \n reduz o recarga de <HighLight> Exile </> , <HighLight> Nebula Aria </> , <HighLight> Trick Performance </> e <HighLight> Record </> em 1 segundo. Se 3 pilhas de <HighLight> Pegadas </> forem consumidas, reduza adicionalmente o recarga de <HighLight> skillname(*id) </> em 2 segundos.",
  [285943353421568] = "Assentamento do Rei da Roda Grande.",
  [285943353421056] = "Gire a roda gigante.",
  [285943353420800] = "Alegrar.",
  [285943353420544] = "Dê um tapinha no peito.",
  [285943353420288] = "Sente-se no lugar.",
  [285943353419776] = "Transforme-se em um babuíno de cabelos cacheados.",
  [285943353419520] = "Para glória da família, avance!",
  [285943353419008] = "Transforme-se em uma cavalaria.",
  [285943353418752] = "Sinta o vento frio e cortante.",
  [285943353418240] = "Transforme-se em uma sombra.",
  [285943353417984] = "Arco-íris!",
  [285943353417728] = "Cancele o estado de transformação atual.",
  [285943353417472] = "Transforme-se em um pequeno elefante.",
  [285943353417216] = "Balançando.",
  [285943353416960] = "Teleporte-se para o lounge da Blackthorn Security Company.",
  [285943353416448] = "Liquidação da caixa de ataque em movimento.",
  [285943353416192] = "Ative o Emblema Sagrado do Sol, fazendo com que os jogadores ao redor entrem incontrolavelmente no estado de 'Louvado seja o Sol'.",
  [285943353415936] = "Toque 'Cidade Natal, Pequena Jasmine'.",
  [285943353415680] = "Segure uma tocha por 30 segundos.",
  [285943353415424] = "O tamanho do corpo aumenta 1,5 vezes por 30 segundos.",
  [285943353413376] = "Mobilizando a capacidade de controle precisa espiritualidade do Espreitador de Mistérios Sequência, aproveitando o fluxo de informações oculto ao redor do corpo e usando-se como âncora para gravar uma formação coberta de padrões estelares do Espreitador de Mistérios e palavras secretas aos pés. Simultaneamente, execute um conjunto de movimentos rituais de mago que estão em conformidade com métodos antigos - selos secretos amarrados com os nós dos dedos, sussurrando encantamentos do Espreitador de Mistérios entre os lábios e levantando as mãos para atrair espíritos sobre o corpo. Cada passo corresponde precisamente ao antigo processo do Ritual de Mistério. O círculo mágico girará lentamente com um brilho roxo claro conforme os movimentos são executados, e os encantamentos serão acompanhados por um zumbido baixo, cheio de atmosfera ritualística. \n Durante este período, os jogadores ao redor podem obter uma habilidade temporária, e usar a habilidade temporária pode adquirir uma nota de conhecimento secreto. \n O usuário ganha +4 de Intuição e +2 de Erudição. Os jogadores que usam a habilidade temporária também podem ganhar +4 de Intuição e +2 de Erudição.",
  [285943353412608] = "Mobilize a percepção precisa do Espreitador de Mistérios Sequência para desmontar, fundir e condensar todas as técnicas básicas de combate que você estudou em um único momento, atingindo instantaneamente uma pose inicial de combate com extremo detalhe. Depois que a postura se recuperar naturalmente, esse campo de força se materializará como um claro fantasma de combate após seu próximo ataque. \n Absorver o fantasma aumenta sua Força em 3 e sua Intuição em 1.",
  [858376326095104] = "Raio Branco Puro",
  [858376326092544] = "Lança Sem Sombra",
  [285943353411328] = "Espie os segredos do inimigo. Se a habilidade Control Break do inimigo estiver ativada recarga , estenda seu recarga em 15 segundos; se a habilidade Control Break do inimigo não estiver ativada recarga , force-a para um recarga de 5 segundos.",
  [285943353411072] = "Mobilize o poder do Mundo Astral ao seu redor para delinear um misterioso mapa estelar, iluminando o céu e invocando um pilar de luz estelar no local alvo para causar dano de área. \n\n <FaintYellow> Star Eclipse Curse </> \n: Inimigos atingidos têm sua cura recebida reduzida. \n <FaintYellow> Orientação Astral </> \n: Após usar Julgamento da Cúpula Estrelada, você ganha Orientação Astral, reduzindo o dano recebido por 15 segundos.",
  [285943353410048] = "Utilizável ao possuir 100 pontos de <HighLight> Conhecimento Místico </>. Acione buffdisc(*id) por *d segundos e convoque uma Torrente de Informações no local do alvo bloqueado. A Torrente de Informações perseguirá alvos inimigos a uma certa velocidade, causando até *d de Dano Mágico por segundo a 4 alvos inimigos dentro do alcance. Cada ataque consome 20 pontos de <HighLight> Conhecimento Místico </> ; ele irá parar automaticamente quando <HighLight> Conhecimento Místico </> for insuficiente. \n5 segundos após o início da Torrente de Informações, o <HighLight> Conhecimento Místico </> consumido por ataque aumenta em 10 pontos. Ao consumir <HighLight> 30 </> / <HighLight> 40 </> / <HighLight> 50 </> / <HighLight> 60 </> / <HighLight> 70 </> pontos de <HighLight> Conhecimento Místico </> , o dano causado aumenta para Spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id) pontos. \nQuando o número de ataques antes da Torrente de Informações parar automaticamente for \n <HighLight> 7 </> / <HighLight> 8 </> / <HighLight> 9 </> , ele causará Spellfielddisc(*id)/spellfielddisc(*id)/spellfielddisc(*id) Dano Mágico aos inimigos dentro do alcance ao terminar e tem um <HighLight> 91% </> de chance básica de <HyperLink stylename=\"M_Link\" u=\"2\"> lançar </> até dois inimigos dentro do alcance.",
  [285943353409792] = "Remova os efeitos de controle <HyperLink stylename=\"M_Link\" u=\"3\"></> de você mesmo, ganhe buffdisc(*id) e o efeito de buffdisc(*id) por 4 <HighLight></> segundos e entre no estado Starlight <HighLight></> por 4 <HighLight></> segundos. \n\n <FaintYellow> Starlight </> : buffdisc(*id), deixando um caminho de luz estelar ao se mover, e os inimigos no caminho de luz estelar são afetados por buffdisc(*id). Usar ativamente uma habilidade sairá do estado Starlight <HighLight></>. Ao sair do estado Starlight <HighLight></> devido ao término da duração ou ao usar uma habilidade, cause dano mágico Spellfielddisc(*id) aos inimigos na área circundante e empurre-os para trás <HyperLink stylename=\"M_Link\" u=\"2\"></> .",
  [285943353409536] = "Desdobre o Gambito das Eras, ganhe <HighLight> 3 </> segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> e, após *f segundos, cause *d Dano Mágico aos inimigos dentro do alcance com uma chance base de *f% de <HyperLink stylename=\"M_Link\" u=\"2\"> lançá-los </>. Reduza simultaneamente Recarga de todas as suas <HighLight> Habilidades de Classe </> em <HighLight> 3 </> segundos. Você pode se mudar durante este período. Ganhe 20 pontos de <HighLight> Conhecimento Místico </> após lançar. \n\n <FaintYellow> Conhecimento Místico </>: A capacidade máxima é de 100 pontos. Atingir 100 pontos desbloqueia a <HighLight> Torrente de Informações da Habilidade do Finalizador </>.",
  [285943353408256] = "Evoca uma Ilusão Misteriosa que não pode ser alvo ou atacada por 10 <HighLight></> segundos. Ganhe 20 pontos de Conhecimento Misterioso <HighLight></> após lançar. A ilusão executará continuamente Bruxaria <HighLight></> (Ataque Básico) para atacar os inimigos, causando dano mágico de Spellfielddisc(*id)/spellfielddisc(*id)/bulletdisc(*id) por segmento, ciclando 3 vezes. Você pode lançar uma habilidade em cadeia durante a duração da Ilusão Misteriosa para trocar de posição com a ilusão; esta troca de posição pode ser acionada no máximo uma vez por lançamento de habilidade. \n\n <FaintYellow> Conhecimento Misterioso </>: Máximo de 100 pontos. Ao atingir 100 pontos, desbloqueie o Vórtice de Conhecimento da Habilidade Finalizador <HighLight></> .",
  [285943353407744] = "Causa dano mágico de Spellfielddisc(*id) aos inimigos na área circundante e repele-os <HyperLink stylename=\"M_Link\" u=\"2\"></> , remove Spellfielddisc(*id) do escudo do inimigo e aplica Redução de Cura <HyperLink stylename=\"M_Link\" u=\"20\"></> por *f segundos calculados como mul(*d**,*d). Você pode lançar em cadeia dentro de 5 <HighLight></> segundos após lançar para se deslocar rapidamente para trás. Ganhe 20 pontos de Conhecimento Misterioso <HighLight></> após lançar. \n\n <FaintYellow> Conhecimento Misterioso </>: Máximo de 100 pontos. Ao atingir 100 pontos, desbloqueie o Vórtice de Conhecimento da Habilidade Finalizador <HighLight></> .",
  [285943353407488] = "Expanda as novas roupas do imperador, ganhando 2,5 <HighLight></> segundos de Super Armadura <HyperLink stylename=\"M_Link\" u=\"11\"></> e buffdisc(*id) (este escudo é aumentado por sua saúde máxima) por 15 <HighLight></> segundos. Após o escudo desaparecer ou ser quebrado, cause dano mágico aos inimigos próximos igual a 5 <HighLight></> vezes a absorção de dano do escudo, até um máximo de Spellfielddisc(*id), com o dano compartilhado entre os inimigos no alcance. Ganhe 20 pontos de Conhecimento Misterioso <HighLight></> após lançar. \n\n <FaintYellow> Conhecimento Misterioso </>: Máximo de 100 pontos. Ao atingir 100 pontos, desbloqueie o Vórtice de Conhecimento da Habilidade Finalizador <HighLight></> .",
  [285943353406720] = "Evoca uma Starlight Cage para causar *d de dano mágico ao alvo bloqueado com uma probabilidade base de 69% <HighLight></> de atordoamento <HyperLink stylename=\"M_Link\" u=\"6\"></> por 1,71 <HighLight></> segundos. Ganhe 20 pontos de Conhecimento Misterioso <HighLight></> após lançar. Quando você possui Infusão de Conhecimento <HighLight></> , esta habilidade ganha Fortalecimento <HighLight></> . \n\n <FaintYellow> Fortalecimento </>: Em vez disso, causa dano mágico de Spellfielddisc(*id) aos inimigos dentro do alcance do alvo bloqueado, com uma probabilidade base de 86% <HighLight></> de aprisionamento <HyperLink stylename=\"M_Link\" u=\"7\"></> por 1,71 <HighLight></> segundos e 86% <HighLight></> probabilidade base de 50% <HighLight></> Lento e aplica 69% <HighLight></> probabilidade base adicional de Atordoamento <HyperLink stylename=\"M_Link\" u=\"6\"></> por 1,71 <HighLight></> segundos ao alvo travado. \n <FaintYellow> Conhecimento Misterioso </>: Máximo de 100 pontos. Ao atingir 100 pontos, desbloqueie o Vórtice de Conhecimento da Habilidade Finalizador <HighLight></> .",
  [285943353406208] = "Faça chover Star Sand na área alvo, causando dano mágico de Spellfielddisc(*id) aos inimigos dentro do alcance e aplicando buffdisc(*id) por 10 segundos. Ganhe 20 pontos de Conhecimento Misterioso <HighLight></> após lançar. Quando você possui Infusão de Conhecimento <HighLight></> , esta habilidade ganha Fortalecimento <HighLight></> . \n\n <FaintYellow> Fortalecimento </>: Star Sand permanece após causar dano mágico de Spellfielddisc(*id), causando dano mágico de Spellfielddisc(*id) a cada 0,7 <HighLight></> segundos e tendo uma probabilidade base de 90% <HighLight></> de aplicar uma camada de buffname(*id) <HighLight></> por 2 <HighLight></> segundos, para um total de 3 <HighLight></> vezes; finalmente, lance monstros inimigos dentro do alcance no ar <HyperLink stylename=\"M_Link\" u=\"2\"></> e cause dano mágico Spellfielddisc(*id) aos inimigos no alcance, com dano aumentado em 10% <HighLight></> para cada camada de buffname(*id) <HighLight></> que o inimigo possui. \n <FaintYellow> buffname(*id) </> : Máximo de 3 <HighLight></> camadas, buffdisc(*id). \n <FaintYellow> Conhecimento Misterioso </>: Máximo de 100 pontos. Ao atingir 100 pontos, desbloqueie o Vórtice de Conhecimento da Habilidade Finalizador <HighLight></> .",
  [285943353404672] = "Dispare um raio no alvo travado para causar *d dano mágico. O feixe irá refratar para alvos inimigos próximos até 3 <HighLight></> vezes, com cada refração reduzindo o dano do feixe ao próximo alvo em 5% <HighLight></> . O feixe tem uma probabilidade básica de 60% <HighLight></> de aplicar Estagnação <HyperLink stylename=\"M_Link\" u=\"6\"></> por 0,7 <HighLight></> segundos; se atingir apenas um alvo, o dano aumenta para *d. Ganhe 20 pontos de Conhecimento Misterioso <HighLight></> após lançar. Quando você possui Infusão de Conhecimento <HighLight></> , esta habilidade ganha Fortalecimento <HighLight></> . \n\n <FaintYellow> Fortalecimento </>: Dano base aumentado para *d, contagem de refração aumentada em 1 e dano não diminui mais após a refração. Se atingir apenas um alvo, o dano aumenta para *d. Aplica buffdisc(*id) a todos os alvos atingidos por 3,5 <HighLight></> segundos; tem uma probabilidade básica de 70% <HighLight></> de reduzir sua velocidade de movimento em 50% <HighLight></> por 2,5 <HighLight></> segundos. Lançar uma Refração de Luz não fortalecida <HighLight></> devolve 2 <HighLight></> segundos de Recarga . \n <FaintYellow> Conhecimento Misterioso </>: Máximo de 100 pontos. Ao atingir 100 pontos, desbloqueie o Vórtice de Conhecimento da Habilidade Finalizador <HighLight></> .",
  [285943353404416] = "Causa *d Dano Mágico ao alvo bloqueado, ganha <HighLight> Infusão de Conhecimento </> e aciona buffdisc(*id) por *d segundos. Ganhe 20 pontos de <HighLight> Conhecimento Místico </> após lançar. \n\n <FaintYellow> Infusão de Conhecimento </>: Faz com que a próxima <HighLight> Bruxaria </> (Ataque Normal) seja <HighLight> Fortalecida </>. Faz com que os próximos dois lançamentos de <HighLight> Refraction of Light </> , <HighLight> Star Sand </> ou <HighLight> Starlight Cage </> sejam <HighLight> Fortalecidos </> ; uma <HighLight> Infusão de Conhecimento </> só pode fortalecer a mesma habilidade uma vez. \n <FaintYellow> Conhecimento Místico </>: A capacidade máxima é de 100 pontos. Atingir 100 pontos desbloqueia a <HighLight> Torrente de Informações da Habilidade do Finalizador </>.",
  [285943353404160] = "Condense uma Lança de Longinus e jogue-a na área designada, causando dano mágico Spellfielddisc(*id)+spellfielddisc(*id)+spellfielddisc(*id) aos inimigos em uma pequena área, aplicando Redução de Cura <HyperLink stylename=\"M_Link\" u=\"20\"></> por *f segundos calculado como mul(*d**,*d), com uma probabilidade base de 50% <HighLight></> de causar 50% <HighLight></> Efeito lento por 3 <HighLight></> segundos. Ganhe simultaneamente 20 pontos de Conhecimento Misterioso <HighLight></>. \n\n <FaintYellow> Conhecimento Misterioso </>: Máximo de 100 pontos. Ao atingir 100 pontos, desbloqueie o Vórtice de Conhecimento da Habilidade Finalizador <HighLight></> .",
  [285943353402624] = "Execute Bruxaria para executar um ataque de três estágios contra inimigos em uma pequena área, causando Dano Mágico de Spellfielddisc(*id)/spellfielddisc(*id)/bulletdisc(*id) respectivamente e <HyperLink stylename=\"M_Link\" u=\"2\"> Interrompendo </> monstros inimigos. Ganhe <HighLight> 6 </> / <HighLight> 5 </> / <HighLight> 13 </> pontos de <HighLight> Conhecimento Místico </> ao acertar. Quando você possui <HighLight> Knowledge Infusion </> , esta habilidade é <HighLight> Fortalecida </> . \n\n <FaintYellow> Fortalecimento </> : Condense três Lanças de Longinus e jogue-as na área designada, causando Spellfielddisc(*id)+spellfielddisc(*id)+spellfielddisc(*id) Dano Mágico aos inimigos em uma área pequena, aplicando um efeito mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> de Redução de Cura </> com duração de *f segundos, com um <HighLight> 50% </> de chance básica de causar um efeito de lentidão de <HighLight> 50% </> por <HighLight> 3 </> segundos. Ganhe simultaneamente 20 pontos de <HighLight> Conhecimento Místico </>. \n <FaintYellow> Conhecimento Místico </>: A capacidade máxima é de 100 pontos. Atingir 100 pontos desbloqueia a <HighLight> Torrente de Informações da Habilidade do Finalizador </>.",
  [514641503530240] = "Salto de Chama",
  [285943353401600] = "Desperte o traço 'Forma de Força' dentro da linhagem do Gigante do Crepúsculo, condensando energia física e força bruta extraordinária ao redor de seu corpo. Ancore a postura de ataque que você está prestes a executar com antecedência, enquanto utiliza o fraco poder do espírito da terra sob seus pés para moldar a trajetória de sua força. Quando você executar seu próximo ataque poderoso, a trajetória da força condensada se materializará como um fantasma de ataque pesado seguindo seus movimentos. \n Absorver o fantasma aumenta seu Charme em 3 e sua Intuição em 1.",
  [285943353401344] = "Desperte o traço de força bruta mais primitivo da linhagem do Gigante do Crepúsculo, concentrando toda a força física e o escasso Beyonder poder na perna esquerda. Ao pisar no chão, a força é transmitida para baixo na textura da terra, provocando um tremor curto e localizado enquanto levanta poeira para criar uma breve obstrução visual. \nAumenta sua Força em 1.",
  [285943353400064] = "Quando em postura ofensiva <HighLight></> , buffdisc(*id). \n Quando em forma de defesa <HighLight></> , buffdisc(*id). \n Ao usar a Forma de Defesa em modos de Competição designados <HyperLink stylename=\"M_Link\" u=\"26\"></>, os valores de Redução de Dano e Dano Aumentado são ajustados e relacionados dinamicamente ao número de jogadores inimigos ao redor: A Redução de Dano varia de 2% a 15%, e o Dano Aumentado varia de 15% a 25%. Quanto mais jogadores inimigos houver, maior será a sua Redução de Dano e Aumento de Dano; outros atributos passivos permanecem inalterados.",
  [285943353399808] = "Expanda um Domínio Crepuscular que segue seu movimento, fazendo com que os inimigos dentro da área sejam continuamente afetados pela Estagnação <HyperLink stylename=\"M_Link\" u=\"6\"></> .",
  [285943353399296] = "Transforme-se em um gigante e ganhe invencibilidade breve <HyperLink stylename=\"M_Link\" u=\"1\"></> , dissipe até 3 status negativos <HyperLink stylename=\"M_Link\" u=\"4\"></> e expanda o Domínio do Crepúsculo <HighLight></> , causando um total de sum(*d,*d,*d,*d,*d) de dano aos inimigos na área circundante. Após o término da transformação, cause *d dano aos inimigos dentro da área. \n Você pode se mover enquanto lança esta habilidade; ganhe buffdisc(*id) e buffdisc(*id). \n\n <FaintYellow> Domínio do Crepúsculo </> \n: Aplica Lentidão continuamente aos inimigos dentro do domínio.",
  [285943353398784] = "Ganhe buffdisc(*id), balance espadas duplas para atacar continuamente os inimigos em uma pequena área à frente, causando um total de soma(*d,*d,*d,*d,*d) de dano físico, interrompendo continuamente <HyperLink stylename=\"M_Link\" u=\"2\"></> monstros inimigos. O golpe final causa *d dano físico e repele <HyperLink stylename=\"M_Link\" u=\"2\"></> monstros inimigos, enquanto invoca um fantasma gigante Spellfielddisc(*id). Esta habilidade causa 10% <HighLight></> de dano aumentado aos inimigos no estado Decadência <HighLight></>. Ganhe 4 Marcas do Crepúsculo <HighLight></> após o lançamento. \n\n <FaintYellow> Marcas Crepusculares </> \n fortalecem a habilidade Finalizador <HighLight></> e Angry Slam <HighLight></> , até um máximo de 6.",
  [285943353398272] = "Evoca um fantasma gigante para causar um total de soma(*d+*d) de dano físico aos inimigos em uma pequena área à frente, aplicando Redução de Cura <HyperLink stylename=\"M_Link\" u=\"20\"></> por *f segundos para atingir os jogadores inimigos, calculado como mul(*d**,*d). Após o lançamento, ganhe 4 Marcas do Crepúsculo <HighLight></> e ganhe 1 <HighLight></> Marca do Crepúsculo <HighLight></> a cada 2 <HighLight></> segundos por 6 segundos. \n\n <FaintYellow> Marcas Crepusculares </> \n fortalecem a habilidade Finalizador <HighLight></> e Angry Slam <HighLight></> , até um máximo de 6.",
  [285943353397760] = "Invoca uma sombra fantasma gigante para bater no chão, causando dano físico massivo.",
  [285943353397248] = "Remove <HyperLink stylename=\"M_Link\" u=\"3\"> efeitos de controle </> de você mesmo, <HyperLink stylename=\"M_Link\" u=\"16\"> restaura uma quantidade fixa de </> sua saúde perdida igual a *f**, causa *d dano físico aos inimigos ao redor e concede <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> por *f segundos, um <HighLight> 20% </> de aumento de velocidade de movimento por 3 segundos e <HighLight> Illusion Breaking </> por *f segundos. \n \n <FaintYellow> Ilusão quebrando </> \nbuffdisc(*id).",
  [285943353396224] = "Evoca uma formação de espada gigante no local do alvo bloqueado, causando dano físico de Spellfielddisc(*id). Ganhe 1 Marca do Crepúsculo <HighLight></> ao lançar. \n Se estiver na Postura Ofensiva <HighLight></> , acertar um inimigo aplica Decay <HighLight></> por 6 <HighLight></> segundos. \n\n <FaintYellow> Twilight Marks </> \n fortalecem a habilidade Finisher <HighLight></> e Angry Slam <HighLight></> , até um máximo de 6. \n <FaintYellow> Decay </> \n: buffdisc(*id), duração da pilha de vários aplicativos, até um máximo de 20 segundos.",
  [285943353395200] = "Ganhe buffdisc(*id), balance espadas duplas para interromper continuamente <HyperLink stylename=\"M_Link\" u=\"2\"></> alvos inimigos e causar um total de soma(*d,*d,*d,*d) de dano físico, finalmente lançando-os no ar <HyperLink stylename=\"M_Link\" u=\"2\"></> com uma probabilidade básica de *f**; ganhe 2 Marcas do Crepúsculo <HighLight></> após o lançamento. \n Se estiver na Postura Ofensiva <HighLight></> , cada golpe em um inimigo aplica Decay <HighLight></> por 6 <HighLight></> segundos. \n\n <FaintYellow> Twilight Marks </> \n fortalecem a habilidade Finisher <HighLight></> e Angry Slam <HighLight></> , até um máximo de 6. \n <FaintYellow> Decay </> \n: buffdisc(*id), duração da pilha de vários aplicativos, até um máximo de 20 segundos.",
  [285943353394432] = "Avança em uma direção designada, causando *d dano físico aos inimigos ao longo do caminho. Ao atingir um inimigo, ganhe 1 Marca do Crepúsculo <HighLight></> . Esta habilidade pode ser carregada 2 <HighLight></> vezes. \n Se estiver em Forma de Defesa <HighLight></> , acertar um inimigo aplica buffdisc(*id) por *f segundos. \n Se estiver na Postura Ofensiva <HighLight></> , acertar um inimigo aplica Decay <HighLight></> por 6 <HighLight></> segundos. \n\n <FaintYellow> Twilight Marks </> \n fortalecem a habilidade Finisher <HighLight></> e Angry Slam <HighLight></> , até um máximo de 6. \n <FaintYellow> Decay </> \n: buffdisc(*id), duração da pilha de vários aplicativos, até um máximo de 20 segundos.",
  [285943353392384] = "Esta habilidade pode ser carregada 3 vezes e possui três técnicas de espada. As técnicas circulam automaticamente após cada lançamento, e diferentes técnicas podem ser encadeadas, causando dano físico *d, sum(*d+*d) e sum(*d+*d) respectivamente. \n Cada segmento consome até 2 Marcas do Crepúsculo <HighLight></> ao lançar para conceder o Fortalecimento desta habilidade <HighLight></> . \n\n <FaintYellow> Fortalecimento </> \n: Consumir 1/2 Marcas do Crepúsculo <HighLight></> aumenta o dano base de cada acerto desta habilidade em *d/*d.",
  [285943353391616] = "Ganhe Super Armadura <HyperLink stylename=\"M_Link\" u=\"11\"></> continuamente, carregando e causando dano físico contínuo aos inimigos próximos por um total de 4 <Highlight></> acertos, cada um causando *d de dano. Após o término da carga, cause *d dano físico aos inimigos próximos. O primeiro ataque detona e remove o Decay <HighLight></> aplicado ao alvo, aumentando o dano em *d a cada 1 segundo de duração restante. \n Consome todas as Marcas do Crepúsculo <HighLight></> ao lançar para conceder a esta habilidade Fortalecimento <HighLight></> . \n\n <FaintYellow> Fortalecimento </> \n: Para cada Marca Crepuscular <HighLight></> consumida, o dano desta habilidade é aumentado em 10% <HighLight></> .",
  [285943353391104] = "Expanda o domínio para fornecer um Escudo de alto valor e <HighLight> 15% </> de Redução de Dano aos dois aliados com a Vida mais baixa dentro do domínio (se você for o único no domínio, a quantidade de Escudo é duplicada), causando *d Dano Físico aos inimigos dentro do alcance. Posteriormente, continue a carregar e ganhe <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> ; após a conclusão, cause *d Dano Físico aos inimigos dentro do alcance. Este dano e o Escudo aumentam com sua Saúde Máxima. \nConsome todas as <HighLight> Marcas do Crepúsculo </> ao lançar para <HighLight> Fortalecer </> esta habilidade. \n\n <FaintYellow> Fortalecimento </> \n: Cada Marca Crepuscular consumida aumenta o Escudo fornecido em <HighLight> 25% </> .",
  [285943353390336] = "Implante um domínio, buffdisc(*id) você mesmo, buffdisc(*id) companheiros de equipe em uma grande área e conceda a si e aos companheiros de equipe <HighLight> 10% </> de Redução de Dano, enquanto causa *d dano físico aos inimigos ao alcance; então, continue a atacar e ganhar <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> , causando *d dano físico aos inimigos ao alcance após a conclusão. Este dano e o escudo são aumentados pela sua saúde máxima. \nConsome todas as <HighLight> Dusk Marks </> ao lançar para <HighLight> fortalecer </> esta habilidade. \n\n <FaintYellow> Fortalecimento </> \nCada Dusk Mark consumido aumenta o escudo fornecido em <HighLight> 25% </> .",
  [285943353389824] = "Ganhe <HighLight> Florete Prateado </> por <HighLight> 20 </> segundos; ganhe 4 pilhas de <HighLight> Dawn </> , com uma pilha de <HighLight> Dawn </> dissipando a cada <HighLight> 5 </> segundos. Ganhe 2 <HighLight> Marcas do Crepúsculo </> ao lançar. Ao lançar outras habilidades, toque nesta habilidade para obter todos os efeitos de buff diretamente. \n\n <FaintYellow> Silver Rapier </> \n: Ao causar dano aos inimigos, execute um ataque coordenado, causando dano físico de bulletdisc(*id). Este efeito tem um <HighLight> 3 </> -segundo interno recarga . \n <FaintYellow> Dawn </> \n: Cada pilha fornece buffdisc(*id). \n <FaintYellow> Twilight Mark </> \n: Fortalece <HighLight> habilidade de finalização </> e <HighLight> Angry Slam </>. Pode conter até 6 marcas.",
  [285943353389312] = "Ganhe buffdisc(*id) por *f segundos (este escudo é aumentado pela sua saúde máxima); quando o escudo é quebrado, você ganha <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> por buffdisc(*id) segundos, com um interno recarga de buffdisc(*id) segundos. Ganhe 1 <HighLight> Dusk Mark </> ao lançar. Ao lançar outras habilidades, toque nesta habilidade para ganhar o escudo diretamente. \nAo carregar esta habilidade: passivadisc(*id). \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes.",
  [285943353361920] = "Lança um ataque de quatro estágios contra inimigos em uma pequena área à frente, causando *d/*d/sum(*d,*d,*d)/sum(*d,*d,*d,*d) de Dano Mágico respectivamente. O quarto estágio <HyperLink stylename=\"M_Link\" u=\"2\"> repele </> monstros inimigos e concede a você <HighLight> Flashback </> . Ao segurar <HighLight> Footprints </> , esta habilidade é substituída por <HighLight> Footprint Reappearance </> . \n\n <FaintYellow> Reaparecimento da pegada </> \nskilldisc(*id)",
  [285943353388288] = "Ataque continuamente os inimigos ao redor, causando *d de dano físico aos inimigos ao alcance a cada <Highlight> 0,4 </> segundos por <Highlight> 5 </> segundos, <HyperLink stylename=\"M_Link\" u=\"2\"> arrastando </> monstros inimigos em sua direção e aplicando buffdisc(*id) aos jogadores inimigos. Ganhe 1 <HighLight> Marca do Crepúsculo </> por segundo durante o lançamento. \nGanhe <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> durante o Sunset Hurricane; você pode se mover durante o lançamento e pode executar um combo após 1 segundo de lançamento para interromper a habilidade e reembolsar uma parte do recarga . \nSe você estiver em <HighLight> Forma de Defesa </> , os ataques serão aplicados <HyperLink stylename=\"M_Link\" u=\"12\"> Provocar </> aos monstros inimigos por *f segundos. \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes.",
  [285943353388032] = "Solta um rugido estonteante, causando *d de dano físico aos inimigos próximos e aplicando, por *f segundos, o efeito buffdisc(*id). Em seguida, convoque uma sombra fantasma gigante para bater no chão, causando dano físico ao Spellfielddisc(*id). \nApós o uso, você entra no estado <HighLight> Power Vacuum </>. \n\n <FaintYellow> Power Vacuum </> \nVocê não pode usar <HighLight> Royal Court Command </> durante este período.",
  [285943353387776] = "Corra rapidamente em direção a um alvo. Se o alvo for um inimigo, causa *d de dano físico às unidades na área de destino, com uma probabilidade base *f** de aplicar <HyperLink stylename=\"M_Link\" u=\"7\"> Aprisionamento </> por *f segundos e causar *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> aos jogadores inimigos. Em seguida, bata para causar *d dano físico aos inimigos próximos, <HyperLink stylename=\"M_Link\" u=\"2\"> derrubando </> monstros inimigos, com uma *f** probabilidade básica de <HyperLink stylename=\"M_Link\" u=\"2\"> interromper </> jogadores inimigos, enquanto ganha 1 <HighLight> Dusk Mark </> ; quando você estiver em <HighLight> Forma de Defesa </> e o alvo for um aliado, remova o controle de multidão suave e os efeitos lentos do aliado e aplique <HighLight> Instant Aid </> , buffdisc(*id) eles por 5 segundos. \n <HighLight> Na Postura Ofensiva </> , cada golpe em um inimigo aplica <Highlight> 6 </> segundos de <HighLight> Decay </> . \nSe você não estiver no estado <HighLight> Power Vacuum </> após o lançamento, esta habilidade se torna <HighLight> Royal Court Command </> por <Highlight> 3 </> segundos; neste estado, o Royal Court Command não tem efeito de derrubar jogadores inimigos em Forma de Defesa. \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes. \n <FaintYellow> Decay </> \nbuffdisc(*id), pilhas de duração com múltiplas aplicações, com duração de até 20 segundos. \n <FaintYellow> Power Vacuum </> \nVocê não pode usar <HighLight> Royal Court Command </> durante este período.",
  [285943353387520] = "Avança rapidamente em direção a um alvo aliado, removendo o controle de grupo suave e os efeitos de lentidão dos aliados na área de destino, proporcionando-lhes 15% de Redução de Dano e 25% de Aceleração por 5 segundos. \nSe você não estiver no estado <HighLight> Power Vacuum </> após o lançamento, esta habilidade se torna <HighLight> Royal Court Command </> por <Highlight> 3 </> segundos. \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes. \n <FaintYellow> Power Vacuum </> \nVocê não pode usar <HighLight> Royal Court Command </> durante este período.",
  [285943353387264] = "Solta um rugido estonteante, causando *d de dano físico aos inimigos próximos e aplicando, por *f segundos, o efeito buffdisc(*id). Em seguida, convoque uma sombra fantasma gigante para bater no chão à sua frente, causando dano físico de Spellfielddisc(*id) e <HighLight> derrubando </> monstros no alcance central. \n <HighLight> Em Defense Form </> , usar isso após Demon Hunter Instant Slash pode <HighLight> derrubar </> jogadores inimigos no centro do alcance; usá-lo após Exorcism Slash não tem o efeito de <HighLight> derrubar </> jogadores. \nApós o uso, você entra no estado <HighLight> Power Vacuum </>. \n\n <FaintYellow> Power Vacuum </> \nVocê não pode usar <HighLight> Royal Court Command </> durante este período.",
  [285943353386752] = "Avança rapidamente em direção a um alvo inimigo, causando *d de dano físico aos inimigos na área de destino, com uma probabilidade base *f** de aplicar <HyperLink stylename=\"M_Link\" u=\"7\"> Aprisionamento </> por *f segundos e causando *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> aos jogadores inimigos. Em seguida, desça para causar *d dano físico aos inimigos próximos, <HyperLink stylename=\"M_Link\" u=\"2\"> derrubando </> monstros inimigos, com uma *f** probabilidade base de <HyperLink stylename=\"M_Link\" u=\"2\"> interromper </> jogadores inimigos, enquanto ganha 1 <HighLight> Dusk Mark </> . \n <HighLight> Na Postura Ofensiva </> , cada golpe em um inimigo aplica <Highlight> 6 </> segundos de <HighLight> Decay </> . \nSe você não estiver no estado <HighLight> Power Vacuum </> após o lançamento, esta habilidade se torna <HighLight> Royal Court Command </> por <Highlight> 3 </> segundos. \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes. \n <FaintYellow> Decay </> \nbuffdisc(*id), pilhas de duração com múltiplas aplicações, com duração de até 20 segundos. \n <FaintYellow> Power Vacuum </> \nVocê não pode usar <HighLight> Royal Court Command </> durante este período.",
  [285943353385728] = "Causa *d dano físico aos inimigos em um alcance retangular na direção do alvo travado, <HyperLink stylename=\"M_Link\" u=\"2\"> arrastando </> eles para sua frente e aplicando <HighLight> 2 segundos </> de <HyperLink stylename=\"M_Link\" u=\"9\"> Estagnação </> aos jogadores inimigos. Em seguida, execute um ataque para baixo para causar *d dano físico aos inimigos ao seu redor, com uma probabilidade base *f** de aplicar <HyperLink stylename=\"M_Link\" u=\"7\"> Aprisionamento </> por *f segundos aos jogadores inimigos e causar *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> . Ao atingir um inimigo, você ganha 1 <HighLight> Dusk Mark </> . \nQuando estiver em <HighLight> Forma de Defesa </> , se o alvo bloqueado for um monstro, aplique <HyperLink stylename=\"M_Link\" u=\"12\"> Provocar </> por *f segundos. \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes.",
  [285943353384704] = "Execute três ataques consecutivos contra inimigos em um pequeno alcance à sua frente, causando sum(*d+*d), sum(*d+*d) e sum(*d+*d+*d) de dano físico respectivamente. Quando o terceiro golpe atinge um inimigo, ele aplica <Highlight> 6 </> segundos de <HighLight> Decay </> , e você ganha 1 <HighLight> Dusk Mark </> . \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes. \n <FaintYellow> Decay </> \nbuffdisc(*id), pilhas de duração com múltiplas aplicações, com duração de até 20 segundos.",
  [285943353383936] = "Execute três ataques consecutivos contra inimigos em um pequeno alcance à sua frente, causando *d, *d e *d de dano físico respectivamente. Após o terceiro ataque atingir um inimigo, você ganha 1 <HighLight> Dusk Mark </> . \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes.",
  [285943353383168] = "Gere uma <HighLight> Porta do Viajante disponível para a equipe </> na sua frente e no local alvo. Os membros da equipe podem interagir com a <HighLight> Porta do Viajante </> para se teletransportar para o local alvo e ganhar <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> e <HighLight> Redução de Dano </> (teletransporte unilateral, pode ser usado no máximo uma vez).",
  [285943353381632] = "Confiando na percepção precisa dos nós espaciais do Trick Master, coloque âncoras espaciais menores dentro de uma caixa de truques especial. Quando a tampa é aberta, espiritualidade é canalizado para ativar uma âncora de partícula de luz, que explode em um flash de luz ofuscante, acompanhado por um efeito sonoro nítido semelhante ao flash de uma câmera. \nAumenta seu Conhecimento em 3 e Poder em 1.",
  [285943353381376] = "Tomando emprestado o espaço básico espiritualidade concedido pelo Aprendiz Sequência , sinta âncoras espaciais e abra um portal para o desconhecido, que o Aprendiz pode usar para viajar. \nSó pode ser usado em Tingen.\n Aumenta sua intuição em 1.",
  [285943353381120] = "Depois de lançar uma habilidade de combate que não seja um Ataque Básico, você ganha 1 pilha de <HighLight> Pegadas </> com duração de *f segundos. \nDepois de lançar uma habilidade de combate que não seja um Ataque Básico ou uma Habilidade Finalizadora, você ganha 1 ponto de <HighLight> Energia Estelar </> . \n\n <FaintYellow> Starlight Energy </> \n <HighLight> Starlight Energy </> pode acumular até 5 pontos. Quando você tiver 3 pontos de <HighLight> Starlight Energy </> , você desbloqueia o <HighLight> Finisher Skill Layered Gate </> . Lançar <HighLight> Layered Gate </> consome <HighLight> Starlight Energy </> , fortalecendo seu efeito. \n <FaintYellow> Pegadas </> \n <HighLight> Pegadas </> podem ser empilhadas até 3 vezes. Lançar o Ataque Básico <HighLight> Flash Strike </> consome todas as <HighLight> Pegadas </> , fortalecendo seu efeito. (Se não acertar, <HighLight> Pegadas </> não serão consumidas.)",
  [285943353380608] = "Invoca uma Starlight Cage, causando dano mágico de Spellfielddisc(*id) aos inimigos dentro do alcance do alvo bloqueado, com uma probabilidade base de <HighLight> 44% </> de <HighLight> 1,1 </> segundos de <HyperLink stylename=\"M_Link\" u=\"7\"> Aprisionamento </> e <HyperLink stylename=\"M_Link\" u=\"7\"> Lentidão </>, e uma probabilidade base adicional de <HighLight> 69% </> de <HighLight> 1,71 </> segundos de <HyperLink stylename=\"M_Link\" u=\"6\"> atordoamento </> no alvo bloqueado.",
  [285943353380096] = "Solta um rugido atordoante, causando *d de dano físico aos inimigos próximos e aplicando, por *f segundos, o efeito de buffdisc(*id). Em seguida, convoque uma sombra fantasma gigante para bater no chão, causando dano físico ao Spellfielddisc(*id).",
  [285943353378560] = "Causa 5 instâncias de *d dano mágico a inimigos ao alcance enquanto <HyperLink stylename=\"M_Link\" u=\"2\"> arrasta </> monstros inimigos, seguido por um golpe final que causa *d dano mágico e <HyperLink stylename=\"M_Link\" u=\"2\"> lança </> monstros inimigos no ar. \nQuando você possui <HighLight> Study </> (entre no estado <HighLight> Study </> lançando a habilidade de combate <HighLight> Space Cage </> ), você ganha <HighLight> Strengthening </> , aumentando cada uma das 5 ocorrências de dano causado aos inimigos ao alcance para *d. O dano do golpe final é aumentado para *d.",
  [285943353378048] = "Causa dano mágico de Spellfielddisc(*id) aos inimigos ao alcance e aplica aleatoriamente um de <HighLight> Falling Rocks </> , <HighLight> Freeze </> ou <HighLight> Hurricane </> . \nQuando você possui <HighLight> Study </> (entre no estado <HighLight> Study </> lançando a habilidade de combate <HighLight> Space Cage </> ), você ganha <HighLight> Fortalecimento </> ; após o lançamento, invoca uma sombra fantasma para atacar os inimigos ao alcance novamente, causando Dano Mágico de Spellfielddisc(*id) e ganhando 1 ponto de <HighLight> Starlight Energy </> ao acertar. \n\n <FaintYellow> Falling Rocks </> \nCause dano mágico de Spellfielddisc(*id) aos inimigos ao alcance, aplique Burn e buffdisc(*id) neles, enquanto <HyperLink stylename=\"M_Link\" u=\"2\"> derruba </> monstros inimigos. \n <FaintYellow> Congelar </> \nCause dano mágico de Spellfielddisc(*id) aos inimigos ao alcance com uma probabilidade base de <HighLight> 66% </> de aplicar, por *f segundos, o efeito buffdisc(*id), enquanto <HyperLink stylename=\"M_Link\" u=\"13\"> congela </> monstros inimigos. \n <FaintYellow> Furacão </> \nInvoca um furacão para <HyperLink stylename=\"M_Link\" u=\"2\"> arrastar continuamente </> monstros inimigos e causar 6 instâncias de dano mágico de Spellfielddisc(*id), com o golpe final <HyperLink stylename=\"M_Link\" u=\"2\"> derrubando </> monstros inimigos.",
  [285943353377536] = "Causa *d dano mágico aos inimigos em um alcance circular à sua frente. \nQuando você possui <HighLight> Study </> (entre no estado <HighLight> Study </> lançando a habilidade de combate <HighLight> Space Cage </> ), você ganha <HighLight> Fortalecimento </> ; após o lançamento, invoca uma sombra fantasma para atacar os inimigos ao alcance novamente, causando Dano Mágico de Spellfielddisc(*id) e ganhando 1 ponto de <HighLight> Starlight Energy </> ao acertar.",
  [285943353377024] = "Dispara continuamente múltiplas balas de ar contra os inimigos, causando 5 ocorrências de dano mágico de bulletdisc(*id) e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> monstros inimigos.",
  [285943353376512] = "Restaure imediatamente a saúde do alvo em *f** de sua saúde máxima e aplique buffdisc(*id) por *f segundos.",
  [285943353375744] = "Condense um machado curto para atacar continuamente os inimigos ao redor por 6 segundos, causando *d de dano mágico a cada <HighLight> 0,8 </> segundos, com uma probabilidade base *f** de aplicar <HighLight> 25% </> Lentidão por *f segundos;",
  [285943353374720] = "Pode ser lançado quando você tiver pelo menos 3 pontos de <HighLight> Starlight Energy </> . Consumir toda a <HighLight> Energia da Luz Estelar </> para esfaquear os inimigos na área, causando 2 instâncias de *d dano mágico, seguido de convocação de várias sombras fantasmas para atacar os inimigos, causando 4 instâncias de *d dano mágico e, finalmente, detonando a Energia da Luz Estelar para causar *d dano mágico. Ao consumir mais de 3 pontos de Starlight Energy, cada ponto adicional consumido aumenta o dano desta habilidade em *f**.",
  [285943353370112] = "Ganhe <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> por *f segundos, <HyperLink stylename=\"M_Link\" u=\"7\"> Aprisione </> inimigos na área alvo por *f segundos e cause *d dano após um pequeno atraso.",
  [285943353369600] = "Remova <HyperLink stylename=\"M_Link\" u=\"3\"> efeitos de Crowd Control </> de você mesmo, ganhe <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> e buffdisc(*id) por *f segundos; causa *d de dano mágico aos inimigos próximos com uma probabilidade base de <HighLight> 100% </> de aplicar, por *f segundos, o efeito buffdisc(*id). Após o lançamento, você pode executar um combo para avançar em direção ao alvo inimigo, causando *d dano mágico com uma probabilidade base de <HighLight> 100% </> de <HyperLink stylename=\"M_Link\" u=\"2\"> lançá-los no ar.</>",
  [285943353369344] = "Registre a <HighLight> Beyonder habilidade </> do alvo Caminho (se gravar um alvo que não seja jogador, uma habilidade aleatória Beyonder desse Caminho é obtida). Após o lançamento, você pode realizar um combo para invocar uma projeção para usar a habilidade <HighLight> Beyonder registrada </> (Beyonder habilidades que não são suas Caminho apenas retêm seus efeitos básicos). \n\n <FaintYellow> Habilidades graváveis </>: \n Bardo: <HyperLink stylename=\"M_Link\" u=\"86054010\" color=\"#f4a067\"> Hurricane Axe </> \n Espectador: <HyperLink stylename=\"M_Link\" u=\"86054020\" color=\"#f4a067\"> Sugestão psicológica </> \n Vidente: <HyperLink stylename=\"M_Link\" u=\"86054030\" color=\"#f4a067\"> Air Bullet </> \n Aprendiz: <HyperLink stylename=\"M_Link\" u=\"86054050\" color=\"#f4a067\"> Nebula Aria </> , <HyperLink stylename=\"M_Link\" u=\"86054052\" color=\"#f4a067\"> Desempenho de truque </> , <HyperLink stylename=\"M_Link\" u=\"86054054\" color=\"#f4a067\"> Exílio </> \n Guerreiro: <HyperLink stylename=\"M_Link\" u=\"86054060\" color=\"#f4a067\"> Comando da Corte Real </> \n Espreitador de mistério: <HyperLink stylename=\"M_Link\" u=\"86054070\" color=\"#f4a067\"> Starlight Cage </>",
  [285943353368320] = "Você ganha <HighLight> Estudo </> por 6 segundos e invoca uma Jaula Espacial no local alvo que dura 5 segundos, causando 3 instâncias de *d dano mágico aos inimigos dentro do alcance. A jaula então desmorona, causando *d dano mágico. \nQuando os inimigos dentro da jaula são atingidos por suas habilidades de combate, você ganha 1 pilha de <HighLight> Tela Dobrável </> por <HighLight> 0,5 </> segundos, e a jaula realiza um ataque coordenado no alvo, causando *d dano mágico em área e aplicando, por *f segundos, o efeito buffdisc(*id). (Há um recarga interno de 1 segundo para o mesmo alvo.) \n\n <FaintYellow> Tela Dobrável </> \nCada pilha de <HighLight> Tela Dobrável </> concede a você <HighLight> Super Armadura </> e <HighLight> 6% de Redução de Dano </>, acumulando até <HighLight> 5 </> vezes, com a duração também acumulando com o número de camadas. \n <FaintYellow> Study </> \nFortalece os efeitos de <HighLight> Nebula Aria </> , <HighLight> Trick Performance </> e <HighLight> Exile </> quando lançado.",
  [285943353367040] = "Aplique <HyperLink stylename=\"M_Link\" u=\"9\"> Estagnação </> e uma redução de 50% na velocidade de movimento aos inimigos ao alcance, cause *d de dano mágico 5 vezes, enquanto <HyperLink stylename=\"M_Link\" u=\"2\"> arrasta </> monstros inimigos, então um golpe final causa *d de dano mágico, <HyperLink stylename=\"M_Link\" u=\"2\"> lançando </> monstros inimigos. \nAo possuir <HighLight> Study </> (lançar habilidade de combate <HighLight> Space Cage </> para entrar no estado <HighLight> Study </>), ganhe <HighLight> Strengthening </> , aumentando cada uma das 5 ocorrências de dano causado aos inimigos ao alcance para *d. O dano causado pelo golpe final é aumentado para *d.",
  [285943353366784] = "Causa *d dano mágico aos inimigos em um alcance circular à frente e aplica *f segundos de mul(*d%,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> . \nAo possuir <HighLight> Estudo </> (lançar habilidade de combate <HighLight> Jaula Espacial </> para entrar no estado <HighLight> Estudo </>), ganhe <HighLight> Fortalecimento </>. Após o lançamento, invoca um remanescente para atacar os inimigos ao alcance novamente, causando Dano Mágico de Spellfielddisc(*id) e ganhando 1 ponto de <HighLight> Energia Nebulosa </> ao acertar.",
  [285943353366016] = "Corra até o alvo travado, ganhando uma breve <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </>, com <HighLight> 80% </> de chance básica de aplicar <HyperLink stylename=\"M_Link\" u=\"6\"> Atordoamento </> por 2 segundos e causar *d de dano mágico ao alvo e aos inimigos ao redor. Dentro de *f segundos após o lançamento, você pode liberar um segundo combo para recuar rapidamente para a posição inicial.",
  [285943353365760] = "Corra na direção que o personagem está enfrentando, ganhando breve <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> , causando dano mágico de Spellfielddisc(*id) aos inimigos ao longo do caminho, com <HighLight> 60% </> de chance básica de aplicar <HyperLink stylename=\"M_Link\" u=\"9\"> Estagnação </> por 1,3 segundos. Esta habilidade pode ser cobrada 2 vezes.",
  [285943353365248] = "Vá até o local alvo, ganhe 0,8 segundos de <HyperLink stylename=\"M_Link\" u=\"1\"> Invencibilidade </> e 2 segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </>, cause *d de dano mágico 4 vezes aos inimigos na área e, em seguida, detone para causar *d de dano mágico adicional, <HyperLink stylename=\"M_Link\" u=\"2\"> derrubando </> monstros inimigos e aplicando *f segundos de mul(*d%,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> .",
  [285943353364736] = "Causa dano mágico de Spellfielddisc(*id) e *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de cura </> aos inimigos ao alcance e aplica aleatoriamente um de <HighLight> Falling Rocks </> , <HighLight> Freeze </> ou <HighLight> Hurricane </> . \nAo possuir <HighLight> Estudar </> (lançar habilidade de combate <HighLight> Jaula Espacial </> para entrar no estado <HighLight> Estudar </>), ganhe <HighLight> Fortalecimento </>. Após o lançamento, invoca um remanescente para atacar os inimigos ao alcance novamente, causando Dano Mágico de Spellfielddisc(*id) e ganhando 1 ponto de <HighLight> Energia Nebulosa </> ao acertar. \n\n <FaintYellow> Falling Rocks </> \n causam dano mágico de Spellfielddisc(*id) aos inimigos ao alcance e aplicam Burn, fazendo com que eles sofram buffdisc(*id), enquanto <HyperLink stylename=\"M_Link\" u=\"2\"> derruba </> monstros inimigos. \n <FaintYellow> Congelar </> \n causa dano mágico de Spellfielddisc(*id) aos inimigos ao alcance e tem <HighLight> 66% </> de chance básica de aplicar, por *f segundos, o efeito de buffdisc(*id), enquanto <HyperLink stylename=\"M_Link\" u=\"13\"> congela </> monstros inimigos. \n <FaintYellow> Furacão </> \n invoca um furacão para <HyperLink stylename=\"M_Link\" u=\"2\"> arrastar continuamente </> monstros inimigos e causar dano mágico de Spellfielddisc(*id) 6 vezes, com o golpe final <HyperLink stylename=\"M_Link\" u=\"2\"> derrubando </> monstros inimigos.",
  [285943353421824] = "Liquidação de espadas de roda gigante.",
  [285943353389056] = "Ataque continuamente os inimigos ao redor, causando *d de dano físico aos inimigos ao alcance a cada <Highlight> 0,4 </> segundos por <Highlight> 5 </> segundos, <HyperLink stylename=\"M_Link\" u=\"2\"> arrastando </> monstros inimigos em sua direção e aplicando buffdisc(*id) aos jogadores inimigos. Ganhe 1 <HighLight> Marca do Crepúsculo </> por segundo durante o lançamento. \nGanhe <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> durante o Sunset Hurricane (removido ao receber dano superior a 50% de sua saúde máxima); você pode se mover durante o lançamento e clicar novamente após 1,5 segundos de lançamento para interromper a habilidade e reembolsar uma parte do recarga . \nSe você estiver em <HighLight> Forma de Defesa </> , os ataques serão aplicados <HyperLink stylename=\"M_Link\" u=\"12\"> Provocar </> aos monstros inimigos por *f segundos. \n\n <FaintYellow> Dusk Mark </> \nFortalece <HighLight> Finisher Skill </> e <HighLight> Angry Slam </> , acumulando até 6 vezes.",
  [285943353356288] = "Contando com a extraordinária coordenação física e o controle preciso da expressão concedidos pelo Palhaço Sequência, o traço central Sequência de \"mascarar o desamparo do destino com aparências absurdas e esconder a tristeza interior com risadas exageradas\" é externalizado em uma performance com forte tensão emocional. \nAumenta seu Carisma em 3 e Conhecimento em 1.",
  [285943353324800] = "Avança rapidamente em direção ao alvo inimigo, com uma probabilidade base de *f** para <HyperLink stylename=\"M_Link\" u=\"2\"> derrubar </> o alvo e os inimigos em uma pequena área ao redor dele, causando *d dano físico e aplicando *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> e *f segundos de <HyperLink stylename=\"M_Link\" u=\"9\"> Estagnação </> . Você ganha <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> durante a corrida. \n Ganhe 1 ponto de <HighLight> Energia Solar </> ao lançar (ganhe 2 pontos de <HighLight> Energia Solar </> no estado <HighLight> Sol Ardente </>). \n Esta habilidade pode ser carregada 2 vezes. \n\n <FaintYellow> Energia Solar </>: Mantenha até 5 pontos. Obtenha Energia Solar para desbloquear e fortalecer <HighLight> Punição </> e <HighLight> Lança Sem Sombra </> .",
  [285942816561664] = "Sair do modo espingarda",
  [285942816524032] = "Efeito Roguelike - Decadência: Causa dano de área quando os inimigos morrem",
  [285943084982784] = "Transforme-se em Sombra",
  [285942816457984] = "Cremar cadáver automaticamente",
  [285942816441856] = "Modelo de descrição dinâmica de habilidade",
  [285943084885504] = "Furacão Machado",
  [285943084879872] = "Queda de meteoro",
  [285943353357568] = "Evoca um Reino de Mistérios na área designada, forçando todos os inimigos a se deslocarem para o centro, causando dano de Spellfielddisc(*id) 6 vezes; em seguida, causa dano finalizador de Spellfielddisc(*id), <HyperLink stylename=\"M_Link\" u=\"2\"> lançando </> inimigos e fazendo-os sofrer <HyperLink stylename=\"M_Link\" u=\"2\"> Estagnação </> por 3,5 segundos. Ao lançar, ganhe uma <HighLight> Carta de Destino </> ; se a última carta obtida foi uma <HighLight> Espiritualidade Carta </> , ganhe uma <HighLight> Espiritualidade Carta </> em vez disso. \n\n <FaintYellow> Carta do Destino </> / <FaintYellow> Espiritualidade Carta </>: Cartões Amarelos e Espiritualidade Enganando o Destino. Quando três <HighLight> Fate Cards </> / <HighLight> Espiritualidade Cards </> forem coletadas, consuma todas as cartas para trocar o <HighLight> Finisher Skill Shuffle </> para <HighLight> Fooling of Fate </> / <HighLight> Espiritualidade Burst </>.",
  [285943353357312] = "Remove todos os <HyperLink stylename=\"M_Link\" u=\"3\"> efeitos de controle de multidão de você mesmo e, após a ativação, concede <HighLight> 0,5 </> segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> . Coloca um farol de chama em sua localização atual e pisca para o local alvo. Causa *d dano físico em uma pequena área ao redor de sua posição original onde você ⟦Desaparece⟧ e do local alvo.",
  [285943890265344] = "Avance com a espada em alta velocidade para atacar, atacando unidades ao longo do caminho e ganhando uma Marca do Crepúsculo (usada para fortalecer o Angry Slam e as habilidades de finalização). Aplica deterioração (dano contínuo) na Postura Ofensiva e aumenta seu bloqueio na Forma de Defesa.",
  [285943085006848] = "Liquidação de acertos sem tiro na cabeça",
  [285943890199296] = "Consuma 3 pontos de Energia Solar para condensar um martelo gigante, esmagando-o com imensa força para causar danos massivos aos inimigos na área. Fortalecido no estado Sol Ardente, com maior alcance de ataque e dano.",
  [285943890183936] = "Causa dano ao alvo bloqueado.",
  [285943353354496] = "O Vidente usa técnicas habilidosas para coletar <HighLight> Cartões Amarelos de Fooling of Fate </> , <HighLight> Espiritualidade Cartões Azuis </> e <HighLight> Card Energy </> , alternando a <HighLight> Finisher Skill </> entre <HighLight> Fooling of Fate </> , <HighLight> Espiritualidade Burst </> e <HighLight> Embaralhar cartas </> e pode aplicar <HighLight> Fooling Mark </> aos inimigos por *f segundos por meio de habilidades. \n\n <FaintYellow> Fooling Mark </> : Depois de acumular 3 vezes, ela detona e é removida, causando mul(*d,3) de dano físico ao alvo pelo lançador.",
  [285943353354240] = "Manipule os fios corpo espiritual do alvo, fazendo com que o alvo caia em um estado de atordoamento forçado de 3 segundos após 10 segundos. Este estado de atordoamento forçado não pode ser removido por habilidades de quebra de controle.",
  [285943353353728] = "Manipule os fios corpo espiritual do alvo para aplicar buffdisc(*id), enquanto implanta um Reino de Mistérios ao redor do alvo, fazendo com que os inimigos ao alcance sofram <HyperLink stylename=\"M_Link\" u=\"9\"> Estagnação </> por *f segundos, causando dano físico de Spellfielddisc(*id) 6 vezes; então, um golpe final causa dano físico em Spellfielddisc(*id). Se o alvo for um monstro, <HyperLink stylename=\"M_Link\" u=\"2\"> lance </> o alvo; se o alvo for um jogador, <HyperLink stylename=\"M_Link\" u=\"6\"> atordoa </> o alvo por *f segundos. Ao lançar, ganhe um <HighLight> Cartão Amarelo Fooling of Fate </> ; se a última carta obtida foi uma <HighLight> Espiritualidade Blue Card </> , ganhe uma <HighLight> Espiritualidade Blue Card </> em vez disso. \n\n <FaintYellow> Cartão Amarelo Fooling of Fate </> / <FaintYellow> Espiritualidade Cartão Azul </> : Quando três <HighLight> Cartões Amarelos Fooling of Fate </> / <HighLight> Espiritualidade Cartões Azuis </> forem coletados, consuma todas as cartas para trocar o <HighLight> Finisher Skill Shuffle </> a <HighLight> Enganação do Destino </> / <HighLight> Espiritualidade Explosão </> .",
  [285943353352704] = "Só pode ser liberado quando <HighLight> Card Energy </> atingir 5 pontos. Consumir 5 pontos de <HighLight> Energia de Carta </> para disparar cartas continuamente no alvo travado por 2,7 segundos, causando dano físico de Spellfielddisc(*id) 12 vezes ao alvo e aos inimigos em uma pequena área, e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> monstros inimigos. Você pode liberar outras habilidades e se mover durante o lançamento. \nEnquanto esta habilidade estiver disponível, a <HighLight> Finisher Skill </> não mudará para <HighLight> Fooling of Fate </> ou <HighLight> Espiritualidade Burst </>, mas eles ainda podem ser desbloqueados coletando <HighLight> Fooling of Fate Yellow Cards </> ou <HighLight> Espiritualidade Blue Cards </> e estará disponível imediatamente após esta habilidade ser lançada.",
  [285943353352448] = "Só pode ser liberado quando <HighLight> Card Energy </> atingir 5 pontos. Consumir 5 pontos de <HighLight> Energia de Carta </> para disparar cartas continuamente no alvo travado por 2,7 segundos, causando dano físico de Spellfielddisc(*id) 12 vezes ao alvo e aos inimigos em uma pequena área, e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> monstros inimigos. Você pode liberar outras habilidades e se mover durante o lançamento. \nEnquanto esta habilidade estiver disponível, a <HighLight> Finisher Skill </> não mudará para <HighLight> Fooling of Fate </> ou <HighLight> Espiritualidade Burst </>, mas eles ainda podem ser desbloqueados coletando <HighLight> Fooling of Fate Yellow Cards </> ou <HighLight> Espiritualidade Blue Cards </> e estará disponível imediatamente após esta habilidade ser lançada.",
  [285943353352192] = "Colete três <HighLight> Espiritualidade Cartões Azuis </> para desbloquear esta habilidade. Causa dano físico de Spellfielddisc(*id) aos inimigos ao alcance e aplica <HighLight> Vulnerabilidade </> por *f segundos, <HyperLink stylename=\"M_Link\" u=\"2\"> lançando </> monstros inimigos. Ganhe um ponto de <HighLight> Energia de Carta </> após lançar. \nConjurar Espiritualidade Burst eliminará os efeitos de auto-buff de Fooling of Fate. \n\n <FaintYellow> Energia da Carta </>: Pode conter até 5 pontos. Ao atingir 5 pontos, a <HighLight> Finisher Skill </> muda e trava para <HighLight> Shuffle Cards </> . \n <FaintYellow> Vulnerabilidade </>: O dano recebido do lançador é aumentado em 10%.",
  [285943353351936] = "Colete três <HighLight> Cartões Amarelos de Fooling of Fate </> para desbloquear esta habilidade. Causa dano físico de Spellfielddisc(*id) aos inimigos ao alcance e aplica uma pilha de <HighLight> Fooling Mark </> ; monstros inimigos são <HyperLink stylename=\"M_Link\" u=\"2\"> interrompidos </> . Então, por *f segundos, seus Ataques Normais têm uma chance de disco passivo(*id) de aplicar uma pilha de <HighLight> Marca de Enganação </> ao alvo, e você ganha buffdisc(*id). Ganhe um ponto de <HighLight> Card Energy </> após lançar. \nLançar Fooling of Fate eliminará o efeito de <HighLight> Vulnerabilidade </> de Espiritualidade Burst. \n\n <FaintYellow> Fooling Mark </> : Depois de acumular 3 vezes, ela detona e é removida, causando mul(*d,3) de dano físico ao alvo pelo lançador. \n <FaintYellow> Energia da Carta </>: Pode conter até 5 pontos. Ao atingir 5 pontos, a <HighLight> Finisher Skill </> muda e trava para <HighLight> Shuffle Cards </> .",
  [285943353350912] = "Limpe-se dos <HyperLink stylename=\"M_Link\" u=\"3\"> efeitos de controle </> , deixe um Substituto de Estatueta de Papel em sua posição que herda suas marcas bloqueadas e salte na direção do joystick (ou para trás por padrão). Ganhe *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> e, por *f segundos, o efeito de buffdisc(*id) ao ser liberado. O substituto da estatueta de papel executará automaticamente três ataques básicos aos inimigos, causando dano físico bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id) respectivamente, e então explodirá para causar *d dano físico aos inimigos próximos.",
  [285943353350400] = "Causa dano físico de Spellfielddisc(*id) aos inimigos ao alcance com uma chance base *f** de aplicar, por *f segundos, o efeito de buffdisc(*id) e uma chance base *f** de <HyperLink stylename=\"M_Link\" u=\"6\"> Atordoar </> inimigos no centro do alcance por 0,8 segundos, até um máximo de <HyperLink stylename=\"M_Link\" u=\"6\"> Atordoar </> 2 alvos. Ao atingir jogadores inimigos, aplique *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> . Ao lançar, ganhe um <HighLight> Cartão Amarelo Fooling of Fate </> e aplique uma pilha de <HighLight> Fooling Mark </> aos inimigos atingidos; se a última carta obtida foi uma <HighLight> Espiritualidade Blue Card </> , ganhe uma <HighLight> Espiritualidade Blue Card </> em vez disso e ganhe um ponto de <HighLight> Card Energy </> . \n\n <FaintYellow> Cartão Amarelo Fooling of Fate </> / <FaintYellow> Espiritualidade Cartão Azul </> : Quando três <HighLight> Cartões Amarelos Fooling of Fate </> / <HighLight> Espiritualidade Cartões Azuis </> forem coletados, consuma todas as cartas para trocar o <HighLight> Finisher Skill Shuffle </> a <HighLight> Enganação do Destino </> / <HighLight> Espiritualidade Explosão </> . \n <FaintYellow> Energia da Carta </>: Pode conter até 5 pontos. Ao atingir 5 pontos, a <HighLight> Finisher Skill </> muda e trava para <HighLight> Shuffle Cards </> . \n <FaintYellow> Fooling Mark </> : Depois de acumular 3 vezes, ela detona e é removida, causando mul(*d,3) de dano físico ao alvo pelo lançador.",
  [285943353350144] = "Limpe-se dos <HyperLink stylename=\"M_Link\" u=\"3\"> efeitos de controle </> e ganhe *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> . Coloque um farol de chama em sua posição atual e, em seguida, pisque para o local alvo. Cause *d dano físico em uma pequena área ao redor do ponto de desaparecimento e do local alvo. \nUm combo pode ser lançado dentro de 3 segundos após o lançamento. Ao liberar o combo, ganhe *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> e volte para a localização do farol de chama, causando *d dano físico novamente em uma pequena área ao redor do seu ponto de desaparecimento e da localização do farol de chama.",
  [285943353349632] = "Limpe-se dos <HyperLink stylename=\"M_Link\" u=\"3\"> efeitos de controle </> , ganhe *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> e ganhe um efeito de 15% de <HighLight> Redução de Dano </> por *f segundos. Coloque um farol de chama em sua posição atual e, em seguida, pisque para o local alvo. Cause *d dano físico em uma pequena área ao redor do ponto de desaparecimento e do local alvo. \nUm combo pode ser lançado dentro de 3 segundos após o lançamento. Ao liberar o combo, ganhe *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> e volte para a localização do farol de chama, causando *d dano físico novamente em uma pequena área ao redor do seu ponto de desaparecimento e da localização do farol de chama.",
  [285943353349376] = "buffdisc(*id), dura *f segundos, ganhando simultaneamente 1 ponto de <HighLight> Card Energy </> e um <HighLight> Espiritualidade Blue Card </> . \n\n <FaintYellow> Fate Yellow Card </> / <FaintYellow> Espiritualidade Blue Card </>: Quando 3 <HighLight> Fate Yellow Cards </> / <HighLight> Espiritualidade Blue Cards </> forem obtidos, consuma todas as cartas para fazer com que as <HighLight> Finisher Skill Shuffle Cards </> mudem para <HighLight> Enganando o Destino </> / <HighLight> Espiritualidade Explosão </> . \n <FaintYellow> Energia da Carta </> : Pode conter até 5 pontos; ao atingir 5 pontos, a <HighLight> Finisher Skill </> muda e trava para <HighLight> Shuffle Cards </> .",
  [285943353349120] = "Reabasteça sua <HighLight> Energia da Carta </> até 5 pontos. Cada ponto de <HighLight> Energia da Carta </> consumido após o lançamento reduz recarga desta habilidade em 5 segundos. \nGanhe três <HighLight> Cartões Amarelos de Enganação do Destino </> ; se você tiver mais <HighLight> Espiritualidade Cartões Azuis </> , ganhe três <HighLight> Espiritualidade Cartões Azuis </> em vez disso. \n\n <FaintYellow> Cartão Amarelo Fooling of Fate </> / <FaintYellow> Espiritualidade Cartão Azul </> : Quando três <HighLight> Cartões Amarelos Fooling of Fate </> / <HighLight> Espiritualidade Cartões Azuis </> forem coletados, consuma todas as cartas para trocar o <HighLight> Finisher Skill Shuffle </> a <HighLight> Enganando o Destino </> / <HighLight> Espiritualidade Explosão </> . \n <FaintYellow> Energia da Carta </>: Pode conter até 5 pontos. Ao atingir 5 pontos, a <HighLight> Finisher Skill </> muda e trava para <HighLight> Shuffle Cards </> .",
  [285943353348864] = "Causa *d de dano físico ao alvo inimigo, enquanto aplica <HyperLink stylename=\"M_Link\" u=\"6\"> Stun </> por *f segundos e, por *f segundos, o efeito de buffdisc(*id).",
  [285943353348352] = "Dispara continuamente balas de ar no alvo travado por 2,7 segundos, causando dano físico bulletdisc(*id) 5 vezes e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> monstros inimigos; você pode se mover enquanto lança e ganhar *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> e *d% de Aceleração após a ativação. Após lançar, ganhe um ponto de <HighLight> Card Energy </> e um <HighLight> Espiritualidade Blue Card </> . \n\n <FaintYellow> Cartão Amarelo Fooling of Fate </> / <FaintYellow> Espiritualidade Cartão Azul </> : Quando três <HighLight> Cartões Amarelos Fooling of Fate </> / <HighLight> Espiritualidade Cartões Azuis </> forem coletados, consuma todas as cartas para trocar o <HighLight> Finisher Skill Shuffle </> para <HighLight> Enganando o Destino </> / <HighLight> Espiritualidade Explosão </> . \n <FaintYellow> Energia da Carta </>: Pode conter até 5 pontos. Ao atingir 5 pontos, a <HighLight> habilidade de finalização </> muda e trava para <HighLight> embaralhar cartas </>",
  [285943353347840] = "Jogue cartas de tarô no alvo e implante uma formação de cartas, causando dano físico de Spellfielddisc(*id) 4 vezes aos monstros inimigos dentro da formação e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> eles. A formação então explode, causando dano físico de Spellfielddisc(*id) e <HyperLink stylename=\"M_Link\" u=\"2\"> lançando </> monstros inimigos dentro do alcance, até um máximo de <HyperLink stylename=\"M_Link\" u=\"2\"> lançando </> 2 alvos. Ao lançar, ganhe um <HighLight> Cartão Amarelo Fooling of Fate </> e aplique uma pilha de <HighLight> Fooling Mark </> aos inimigos atingidos pela explosão; se a última carta obtida foi uma <HighLight> Espiritualidade Blue Card </> , ganhe uma <HighLight> Espiritualidade Blue Card </> em vez disso e ganhe um ponto de <HighLight> Card Energy </> após o acerto da explosão. \n\n <FaintYellow> Cartão Amarelo Fooling of Fate </> / <FaintYellow> Espiritualidade Cartão Azul </> : Quando três <HighLight> Cartões Amarelos Fooling of Fate </> / <HighLight> Espiritualidade Cartões Azuis </> forem coletados, consuma todas as cartas para trocar o <HighLight> Finisher Skill Shuffle </> a <HighLight> Enganação do Destino </> / <HighLight> Espiritualidade Explosão </> . \n <FaintYellow> Energia da Carta </>: Pode conter até 5 pontos. Ao atingir 5 pontos, a <HighLight> Finisher Skill </> muda e trava para <HighLight> Shuffle Cards </> . \n <FaintYellow> Fooling Mark </> : Depois de acumular 3 vezes, ela detona e é removida, causando mul(*d,3) de dano físico ao alvo pelo lançador.",
  [285943353347328] = "Executa um ataque de três estágios aos inimigos em uma área frontal em forma de leque, com cada estágio causando *d dano físico e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> monstros inimigos. O terceiro estágio aplica uma pilha de <HighLight> Fooling Mark </> e tem uma probabilidade base de *d** para <HyperLink stylename=\"M_Link\" u=\"2\"> repelir </> o inimigo, aplicando um efeito de *f-second mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Healing Reduction </>, enquanto você ganha um <HighLight> Fate Yellow Card </> . \n\n <FaintYellow> Fate Yellow Card </> / <FaintYellow> Espiritualidade Blue Card </> : Quando você obtiver três <HighLight> Fate Yellow Cards </> / <HighLight> Espiritualidade Blue Cards </>, consuma todas as cartas para trocar as <HighLight> Finisher Skill Shuffle Cards </> por <HighLight> Enganando o Destino </> / <HighLight> Espiritualidade Explosão </> . \n <FaintYellow> Fooling Mark </> : Ao acumular 3 vezes, ela detona e é removida, causando mul(*d,3) de dano físico ao alvo do lançador.",
  [285943353347072] = "Executa um ataque de três estágios aos inimigos em uma área frontal em forma de leque, com cada estágio causando *d dano físico e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> monstros inimigos. Após o lançamento do primeiro estágio, você ganha buffdisc(*id) por 6 segundos. O terceiro estágio aplica uma pilha de <HighLight> Fooling Mark </> e tem uma probabilidade base de *d** para <HyperLink stylename=\"M_Link\" u=\"2\"> repelir </> o inimigo, aplicando um efeito de *f-second mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Healing Reduction </>, enquanto você ganha um <HighLight> Fate Yellow Card </> . \n\n <FaintYellow> Fate Yellow Card </> / <FaintYellow> Espiritualidade Blue Card </> : Quando você obtiver três <HighLight> Fate Yellow Cards </> / <HighLight> Espiritualidade Blue Cards </>, consuma todas as cartas para trocar as <HighLight> Finisher Skill Shuffle Cards </> por <HighLight> Enganando o Destino </> / <HighLight> Espiritualidade Explosão </> . \n <FaintYellow> Fooling Mark </> : Ao acumular 3 vezes, ela detona e é removida, causando mul(*d,3) de dano físico ao alvo do lançador.",
  [285943353346048] = "Lança cartas para realizar um ataque de quatro estágios no alvo, causando dano físico bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id) respectivamente e <HyperLink stylename=\"M_Link\" u=\"2\"> interrompendo </> monstros inimigos. A cada 4 vezes que você revela uma carta e causa dano, você ganha uma <HighLight> carta amarela do destino </> ; se a última carta obtida foi uma <HighLight> Espiritualidade Blue Card </> , você ganha uma <HighLight> Espiritualidade Blue Card </> em vez disso. \n\n <FaintYellow> Fate Yellow Card </> / <FaintYellow> Espiritualidade Blue Card </> : Quando você obtiver três <HighLight> Fate Yellow Cards </> / <HighLight> Espiritualidade Blue Cards </>, consuma todas as cartas para trocar as <HighLight> Finisher Skill Shuffle Cards </> para <HighLight> Enganando o Destino </> / <HighLight> Espiritualidade Explosão </> .",
  [285943353345792] = "Usado em um único jogador inimigo para ver através de seu coração e plantar uma <Highlight> Sugestão </> enganosa, com duração de <Highlight> 3 </> segundos. \n Quando o alvo sugerido usa uma habilidade, o dano causado é transferido para seus companheiros de equipe e a cura causada é transferida para seus inimigos. \n O dano causado aos companheiros de equipe devido à Perturbação Mental não pode derrotá-los diretamente.",
  [285943353345536] = "Mobiliza a observação do Espectador Sequência espiritualidade , que integra propriedades curativas, para tocar suavemente o campo emocional superficial do alvo. Sem interferir nos estados mentais profundos ou torcer à força as raízes das emoções, ele apenas converte as emoções negativas originais do alvo em positivas através da orientação emocional. Após a conversão, um espectro claro da nova emoção surgirá em torno do alvo, e esta emoção positiva permanecerá estável por um período de tempo. \n Concede ao alvo +4 Conhecimento e +2 Carisma.",
  [285943353345280] = "Mobiliza a percepção emocional avançada do Espectador Sequência, usando o espectro emocional central do dia do alvo (marcado por Sequência 9 habilidades) como uma âncora para travar no fluxo superficial de consciência do alvo e ler seus pensamentos atuais, não ocultos e concretos. \n Concede ao alvo +3 de Intuição e +1 de Conhecimento.",
  [285943353345024] = "Mobiliza a observação do Espectador Sequência espiritualidade, usando você mesmo como uma âncora para a percepção emocional para condensar uma partícula de luz pálida ao lado do alvo. A cor da partícula corresponde estritamente ao humor superficial do dia do alvo. \n Concede ao alvo +1 de Carisma.",
  [285943353344768] = "O ataque básico Burn acumula até 3 vezes para desencadear uma explosão de alcance e limpar as pilhas.",
  [285943353344512] = "Nesta postura, seus atributos ofensivos além do ataque mágico não fornecem mais bônus de cura e a quantidade de cura é significativamente reduzida. \n Nesta postura, quando você causa dano, você restaura a saúde do disco passivo(*id) para si mesmo.",
  [285943353344000] = "Quando estiver em um estado dissipado, você pode <HyperLink stylename=\"M_Link\" u=\"22\"> Despertar </> e restaurar 50% da Saúde.",
  [285943353343488] = "<HyperLink stylename=\"M_Link\" u=\"22\"> Desperte </> membros do esquadrão ou equipe dissipados, fazendo com que eles revivam na posição de lançamento do Espectador e restaurem 50% de sua Saúde.",
  [285943353342720] = "<HighLight> Estágio 1 </> : O Espectador remove seu próprio Controle de Multidão, e um Mar de Subconsciente se desdobra a seus pés, restaurando continuamente a Saúde dos alvos aliados dentro do alcance por até 9 segundos; companheiros de equipe no Mar do Subconsciente ganham Redução de Dano. \n <HighLight> Estágio 2 </> : O Espectador dissipa o Mar do Subconsciente e restaura a Saúde dos alvos aliados dentro do alcance; quanto menor a duração do Mar do Subconsciente, maior será a quantidade de cura.",
  [285943353342464] = "Remove alguns efeitos de controle de <HyperLink stylename=\"M_Link\" u=\"3\"> de você mesmo e cria um campo que fornece cura contínua aos aliados dentro do alcance, restaurando a Vida de Spellfielddisc(*id) por segundo por <Highlight> 9 </> segundos.",
  [285943353342208] = "Cura continuamente aliados dentro do alcance, restaurando *d Saúde dos aliados a cada 1,5 segundos, até 7 vezes. Você pode mover e lançar outras habilidades enquanto esta habilidade estiver ativa.",
  [285943353341696] = "Cura continuamente aliados dentro do alcance, restaurando *d Saúde aos aliados dentro do alcance a cada 1,5 segundos, até 7 vezes. Você pode mover e lançar outras habilidades enquanto esta habilidade estiver ativa. \n Disponível apenas em <HighLight> Postura de Imaginação </> ; muda para <HighLight> Mind Fire </> em <HighLight> Nightmare Stance </>.",
  [285943353340928] = "Libera Mind Fire, com uma probabilidade base *d** de <HyperLink stylename=\"M_Link\" u=\"7\"> Aprisionar </> inimigos na frente por *f segundos e causar Dano Mágico de Spellfielddisc(*id). Ele então avança, irrompendo para causar *d dano mágico aos inimigos em uma grande área, aplicando mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> por *f segundos, e deixando para trás uma zona de fogo que dura 4 segundos, causando dano mágico de Spellfielddisc(*id) aos inimigos dentro do alcance a cada 0,7 segundos. Quando esta habilidade causa dano, ela tem uma probabilidade *f** de aplicar 1 pilha de <HighLight> Marca de Indução </> por *f segundos. \n Disponível apenas em <HighLight> Postura de Pesadelo </> ; muda para <HighLight> Psicoterapia </> em <HighLight> Postura de Imaginação </>. \n \n <FaintYellow> Marca de Indução </>: Depois de empilhar 3 vezes, há uma probabilidade básica de <Highlight> 100% </> de entrar no estado de <HyperLink stylename=\"M_Link\" u=\"14\"> Hipnose </> por <Highlight> 1,5 </> segundos.",
  [285943353340672] = "Remove efeitos de <HyperLink stylename=\"M_Link\" u=\"3\"> Crowd Control </> de você mesmo, entra no estado <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> e ganha buffdisc(*id) por *f segundos.",
  [285943353340416] = "Afeta até 6 alvos simultaneamente por 6s; durante este período, a Defesa dos alvos é reduzida e eles sofrem danos. Os inimigos dentro da Dream Weaving e aqueles afetados pela Peste Mental são imobilizados.",
  [285943353339904] = "Faz com que os membros do grupo em um raio de 25 metros ganhem uma <HighLight> Heart Healing Mark </> , com duração de *f segundos. Se a distância entre o portador da <HighLight> Marca de Cura do Coração </> e o lançador exceder 70 metros, o portador perderá a <HighLight> Marca de Cura do Coração </>. Esta habilidade tem uma festa de 20 segundos Recarga . \nDisponível apenas em <HighLight> Postura de Imaginação </> ; muda para <HighLight> Frenzy </> em <HighLight> Nightmare Stance </> . \n\n <FaintYellow> Marca de Cura do Coração </>: O portador ganha *d** Redução de Dano. Quando o lançador da marca usa uma habilidade de combate para realizar a Cura, o detentor da marca recupera Saúde igual a 80% da quantidade de cura (afetada pela Redução de Cura do alvo).",
  [285943353339648] = "Faz com que um membro do grupo alvo ganhe uma <HighLight> Marca de Leitura da Mente </> , com duração de *f segundos. Um Espectador só pode ter um alvo com uma <HighLight> Marca de Leitura da Mente </> por vez, e um alvo só pode ter uma <HighLight> Marca de Leitura da Mente </> de um Espectador por vez. Se a distância entre o portador da <HighLight> Marca de Leitura da Mente </> e o lançador exceder 70 metros, o portador perderá a <HighLight> Marca de Leitura da Mente </>. \nDisponível apenas em <HighLight> Postura de Imaginação </> ; muda para <HighLight> Frenzy </> sob <HighLight> Nightmare Stance </> . \n\n <FaintYellow> Marca de Leitura da Mente </> : Quando a Saúde do titular cai abaixo de 30%, ele ganha, por *f segundos, buffdisc(*id); este efeito tem um Recarga de 20 segundos. Quando o lançador da marca usa uma habilidade de combate para realizar a Cura, o detentor da marca recupera Saúde igual a 30% da quantidade de cura (afetada pela Redução de Cura do alvo).",
  [285943353339392] = "Entra no estado <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> e buffdisc(*id), curando continuamente aliados dentro do alcance para Spellfielddisc(*id) Saúde por segundo, enquanto ataca inimigos dentro do alcance para causar dano de Spellfielddisc(*id) por segundo por <Highlight> 6,5 </> segundos.",
  [285943353338880] = "Entra no estado <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> e buffdisc(*id), curando continuamente os aliados dentro do alcance em Spellfielddisc(*id) Health por segundo durante 6,5 segundos. \n Você pode se mover enquanto lança esta habilidade; pode ser interrompido por outras habilidades após 3 segundos, e o efeito de cura ainda persistirá após ser interrompido.",
  [285943353338368] = "Causa dano mágico de Spellfielddisc(*id) a inimigos em alcance frontal, aplica, por *f segundos, mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> e tem uma probabilidade base *d** de aplicar, por *f segundos, buffdisc(*id). \n Disponível apenas em <HighLight> Postura de Pesadelo </> ; muda para <HighLight> Leitura da Mente </> em <HighLight> Postura de Imaginação </>.",
  [285943353338112] = "Restaura instantaneamente *f** da Vida máxima do alvo aliado (a quantidade restaurada não excede *f** da sua própria Vida máxima) e concede-lhe buffdisc(*id) por *f segundos. Quando esta habilidade causa sobrecura, ela restaura a Saúde do membro da equipe com a menor porcentagem de Saúde dentro do alcance da habilidade, com a quantidade restaurada igual à cura excedente (afetada pela Redução de Cura do alvo). \n Esta habilidade pode ser carregada 2 vezes. \n Disponível apenas em <HighLight> Postura de Imaginação </> ; muda para <HighLight> Dream Weaving </> em <HighLight> Nightmare Stance </>.",
  [285943353337344] = "Cria um campo que causa dano mágico de Spellfielddisc(*id) aos inimigos dentro do alcance a cada segundo por 8 segundos. \n Disponível apenas em <HighLight> Postura de Pesadelo </> ; muda para <HighLight> Sugestão Psicológica </> em <HighLight> Postura de Imaginação </>.",
  [285943353337088] = "Dispara balas curativas em aliados, restaurando a saúde do bulletdisc(*id). Ao atingir um alvo, a bala de cura ricocheteará no esquadrão ou nos membros da equipe, restaurando a saúde do próximo alvo. Ela pode ricochetear até 3 vezes, e cada ricochete reduz a quantidade de cura da bala em 30%.",
  [285943353336576] = "Causa dano mágico de Spellfielddisc(*id) ao alvo bloqueado e aos inimigos ao redor, e <HyperLink stylename=\"M_Link\" u=\"2\"> flutua </> monstros inimigos no estado <HighLight> Peste </>.",
  [285943353335552] = "Cria um campo e restaura *d Saúde instantaneamente aos aliados dentro do alcance; o campo dura 6 segundos e os aliados dentro dele restauram *d Saúde por segundo e recebem buffdisc(*id).",
  [285943353334784] = "Causa *d de dano mágico aos inimigos na área e aplica <HighLight> Praga </> por *f segundos. \n\n <FaintYellow> Praga </> : buffdisc(*id).",
  [285943353334528] = "Causa dano mágico de Spellfielddisc(*id) aos inimigos dentro do alcance e aplica <HighLight> Vulnerabilidade </> por *f segundos. \n \n <FaintYellow> Vulnerabilidade </>: buffdisc(*id) 5%.",
  [285943353333760] = "Um combo de três estágios que pacifica as mentes dos aliados, cada estágio restaurando *d/*d/*d Saúde dos alvos aliados. \n Disponível apenas em <HighLight> Postura de Imaginação </> ; muda para <HighLight> Choque de Consciência </> em <HighLight> Postura de Pesadelo </>.",
  [285943353332992] = "Um combo de três estágios que lança ataques de energia mental, cada estágio causando dano mágico bulletdisc(*id)/bulletdisc(*id)/bulletdisc(*id) aos inimigos. \n Disponível apenas em <HighLight> Postura de Pesadelo </> ; muda para <HighLight> Pacificar </> em <HighLight> Postura de Imaginação </>.",
  [285943353332480] = "Após a ativação, o Damage Boost aumenta em 30% por 10 segundos. Registra o dano total que você causa aos inimigos durante este período e, ao final do efeito, causa dano único aos alvos dentro do alcance igual ao dano total registrado.",
  [285943353332224] = "Concede aos companheiros a habilidade <HyperLink stylename=\"M_Link\" u=\"21\"> Purificação </> por 6 segundos. \n Durante este tempo, quando um companheiro de equipe derrota um jogador inimigo, eles irão <HyperLink stylename=\"M_Link\" u=\"21\"> Purificar </> o alvo após um pequeno atraso; esse efeito pode ser acionado até 3 vezes.",
  [285943353331968] = "Usando a piedade sincera como guia, rompa a fina barreira entre a realidade e o domínio do Sol, invocando um feixe de Luz Sagrada que cai sobre você, livre de quaisquer impurezas mundanas. A Luz Sagrada envolve seu corpo como água suave, lavando lentamente a sujeira manchada em seu espiritualidade, a exaustão mental remanescente da batalha e a confusão que nasce dentro de você. \n Concede a si mesmo +4 de Conhecimento e +2 de Carisma.",
  [285943353331712] = "Recite uma breve oração relacionada ao Sol, atraindo um fio de luz sagrada condensada, mas não abrasadora, que pousa precisamente na cabeça do alvo, formando um feixe flutuante continuamente. \n Concede ao alvo +3 de Força e +1 de Conhecimento. \n Usar isso consecutivamente no mesmo alvo pode transformar o feixe acima de sua cabeça em dois ou três feixes.",
  [285943353331200] = "Cante um hino usando palavras que ressoem com a divindade do Sol, concedendo a si mesmo +1 de Carisma. \n Durante esse período, os jogadores ao redor podem ganhar uma habilidade temporária para participar do Praising the Sun; os jogadores que participam do Praising the Sun também ganham +1 de Carisma.",
  [285943353330944] = "Quando <HighLight> Punishment </> e <HighLight> Unshadowed Spear </> atingem um alvo, eles aplicam uma marca de <HighLight> Heresy </> por 5 segundos. \n <HighLight> Blazing Sun </> estado: Ataque Básico <HighLight> Blazing Sun Slash </> e habilidades básicas também aplicam uma marca de <HighLight> Heresia </> ao atingir um alvo. \n \n <HighLight> Heresia </>: Alvos com uma marca <HighLight> Heresia </> recebem 10% a mais de dano de todas as fontes de Bardo.",
  [285943353330688] = "Você ganha o efeito <HighLight> Energy Surge </>. Ao lançar <HighLight> Punishment </> e <HighLight> Unshadowed Spear </> , ganhe 1 pilha de <HighLight> Judgment of Justice </> , com duração de 15 segundos, acumulando até 3 vezes. \n <HighLight> Blazing Sun </> estado: Lançar Ataque Básico <HighLight> Blazing Sun Slash </> e habilidades de combate também adicionam 1 pilha de <HighLight> Julgamento da Justiça </> para você mesmo. \n \n <HighLight> Energy Surge </> : Derrotar um jogador inimigo concede 5 pontos de <HighLight> Espiritualidade </> ; Purificar um jogador inimigo concede 5 pontos de <HighLight> Espiritualidade </> ; participar de uma assistência para derrotar um jogador inimigo concede 1 ponto de <HighLight> Espiritualidade </> , ativando no máximo uma vez por segundo. \n <HighLight> Julgamento da Justiça </>: Cada pilha de <HighLight> Julgamento da Justiça </> aumenta o dano de <HighLight> Punição </> e <HighLight> Lança Sem Sombra </> em 5%.",
  [285943353330176] = "Atinge o alvo com uma rodada de Raios Brancos Puros, atacando 5 vezes no total. Cada acerto causa dano crescente, que diminui com base no número de alvos atingidos dentro do alcance, compartilhado por até 3 alvos.",
  [285943353329664] = "Entre no estado <HighLight> Sol Ardente </> por *f segundos, ganhando *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> . \n Ganhe o efeito passivo <HighLight> Alma do Sol Ardente </>. \n \n <FaintYellow> Blazing Sun </> : A velocidade de movimento aumenta em *f**, a eficiência de ganhar <HighLight> Espiritualidade </> de habilidades de combate aumenta, a dificuldade de ativação para <HighLight> Julgamento de Justiça </> e <HighLight> Veredicto de Heresia </> é reduzida; Ataques básicos <HighLight> Blazing Sun Slash </> , <HighLight> Unshadowed Spear </> e <HighLight> Punishment </> são fortalecidos. \n <FaintYellow> Alma do Sol Ardente </> : Ao receber dano fatal, retém 1 de Vida e ganha *f segundos de <HyperLink stylename=\"M_Link\" u=\"1\"> Invencibilidade </> , removendo quaisquer efeitos de <HyperLink stylename=\"M_Link\" u=\"3\"> Controle de Multidão </>. Durante este período, ganhe 5 pontos de <HighLight> Espiritualidade </> a cada 0,25 segundos, os recarga de <HighLight> Unshadowed Spear </> são reduzidos a 0 e o Damage Boost aumenta em *f** (para cada inimigo adicional, o Damage Boost aumenta em um *f** extra, até um máximo de mul(*f**,*d)). Você ganha <HighLight> 80% </> <HyperLink stylename=\"M_Link\" u=\"10\"> Ferimento Grave </> e derrotar um inimigo restaura <HyperLink stylename=\"M_Link\" u=\"16\"> um valor fixo de </> 20% de Vida. <HighLight> Soul of the Blazing Sun </> tem um interno recarga de *f segundos. \n",
  [285943353329152] = "Remove efeitos de <HyperLink stylename=\"M_Link\" u=\"3\"> Crowd Control </> de você mesmo. Restaura *f** Saúde, concede *f segundos de <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armor </> e *f segundos de buffdisc(*id), enquanto causa *d dano físico aos inimigos próximos.",
  [285943353328384] = "Só pode ser lançado quando <HighLight> Espiritualidade </> tiver pelo menos 3 pontos. Consome 3 pontos de <HighLight> Espiritualidade </> (nenhuma energia consumida se errar ao entrar em combate), causando *d de dano físico aos inimigos em alcance frontal e <HyperLink stylename=\"M_Link\" u=\"2\"> Derrubando </> monstros inimigos. Estado \n <HighLight> Blazing Sun </>: Esta habilidade ganha efeitos adicionais: o número máximo de alvos atingidos aumenta, o alcance do ataque se expande, o dano base aumenta para *d, e se o alvo tiver o efeito <HighLight> Heresia </>, aumenta ainda mais para *d.",
  [285943353327104] = "Ganhe 1 ponto de <HighLight> Espiritualidade </> (ganhe 2 pontos de <HighLight> Espiritualidade </> enquanto estiver no estado <HighLight> Sol Ardente </>). Por *f segundos, ganhe buffdisc(*id); um segundo combo pode ser lançado dentro de 16 segundos após o primeiro lançamento, removendo os efeitos de <HyperLink stylename=\"M_Link\" u=\"3\"> Crowd Control </> de você. \n \n <FaintYellow> Espiritualidade </> : Segure até 5 pontos. Obtenha Espiritualidade para desbloquear e fortalecer <HighLight> Punishment </> e <HighLight> Unshadowed Spear </>.",
  [285943353326336] = "Envolvido em Chamas Sagradas, lançar isso imediatamente aciona Purificação e depois restaura <HighLight> Espiritualidade </> . Ele causa *d dano físico aos inimigos ao redor, <HyperLink stylename=\"M_Link\" u=\"21\"> Purifica </> inimigos em um estado dissipado dentro de um grande raio centrado em você e desencadeia uma explosão após a purificação, causando dano físico de Spellfielddisc(*id) aos inimigos. \n \n <FaintYellow> Espiritualidade </> : Segure até 5 pontos. Obtenha Espiritualidade para desbloquear e fortalecer <HighLight> Punishment </> e <HighLight> Unshadowed Spear </>.",
  [285943353325824] = "Invoca a Luz Sagrada para se fortalecer. Ganhe 2 pontos de <HighLight> Energia Solar </> imediatamente após lançar (ganhe 3 pontos de <HighLight> Energia Solar </> imediatamente no estado <HighLight> Sol Ardente </>), depois ganhe 1 ponto de <HighLight> Energia Solar </> por segundo durante 5 segundos; seu aumento de dano físico é aumentado em *d** por *f segundos. \n\n <FaintYellow> Energia Solar </>: Mantenha até 5 pontos. Obtenha Energia Solar para desbloquear e fortalecer <HighLight> Punição </> e <HighLight> Lança Sem Sombra </>.",
  [285943353325312] = "<HighLight> Energia Solar </> deve ter pelo menos 2 pontos para ser lançada. Consome toda a <HighLight> Energia Solar </> , causando *d dano físico ao alvo bloqueado e ativando <HighLight> Unshadowed </> . O estado \n <HighLight> Blazing Sun </> concede um efeito adicional: Perde *f** de sua Saúde atual e causa <HyperLink stylename=\"M_Link\" u=\"15\"> Dano Fixo </> ao alvo igual ao maior de sua Saúde atual ou Saúde perdida multiplicada por mul(*f**,*f). Jogue pequenas lanças em outros inimigos em um raio de 8 metros afetados por <HighLight> Heresy </> , causando dano físico de Spellfielddisc(*id) e ativando <HighLight> Unshadowed </> . \nDerrotar um jogador inimigo redefine o Recarga desta habilidade. \n\n <FaintYellow> Unshadowed </> : Ao consumir 3/4/5 pontos de Energia Solar, o dano base é aumentado em *d**/mul(*d**,2)/mul(*d**,3). Se o alvo for um jogador e sua Saúde estiver abaixo de *d**, o valor base deste dano é aumentado em 15% (aumentado em 30% no estado <HighLight> Blazing Sun </>). Se este dano derrotar um jogador inimigo, o alvo será <HyperLink stylename=\"M_Link\" u=\"21\"> Purificado </> após um curto período.",
  [285943353325056] = "<HighLight> Energia Solar </> deve ter pelo menos 2 pontos para ser lançada. Consome toda a <HighLight> Energia Solar </> , causando *d dano físico ao alvo bloqueado e ativando <HighLight> Unshadowed </> . O estado \n <HighLight> Blazing Sun </> concede um efeito adicional: Perde *f** de sua Saúde atual e causa <HyperLink stylename=\"M_Link\" u=\"15\"> Dano Fixo </> ao alvo igual ao maior de sua Saúde atual ou Saúde perdida multiplicada por mul(*f**,*f). Jogue pequenas lanças em outros inimigos em um raio de 8 metros afetados por <HighLight> Heresy </> , causando dano físico de Spellfielddisc(*id) e ativando <HighLight> Unshadowed </> . \nDerrotar um jogador inimigo redefine o Recarga desta habilidade. \n\n <FaintYellow> Sem Sombra </> : Ao consumir 3/4/5 pontos de Energia Solar, o dano base é aumentado em *d**/mul(*d**,2)/mul(*d**,3). Se o alvo for um jogador e sua Saúde estiver abaixo de <HighLight> 30% </> , o valor base deste dano é aumentado em <HighLight> 15% </> (aumentado em <HighLight> 30% </> no estado <HighLight> Sol Ardente </>). Se este dano derrotar um jogador inimigo, o alvo será <HyperLink stylename=\"M_Link\" u=\"21\"> Purificado </> após um curto período.",
  [285943353322752] = "Investe contra o inimigo designado, <HyperLink stylename=\"M_Link\" u=\"2\"> repelindo-o continuamente </> e causando 5 ocorrências de *d dano físico, derrubando outros inimigos no caminho e causando *d dano físico; em seguida, desfere um golpe final com a alabarda, causando *d dano físico em área, <HyperLink stylename=\"M_Link\" u=\"2\"> repelindo </> o alvo e aplicando *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> e *f segundos de <HyperLink stylename=\"M_Link\" u=\"9\"> Estagnação </> . Você ganha <HyperLink stylename=\"M_Link\" u=\"11\"> Super Armadura </> durante a investida. Quando o alvo da carga tiver Super Armadura, você interromperá a investida, causará *d dano físico a ele e aplicará o efeito adicional do golpe final. \n Ganhe 1 ponto de <HighLight> Energia Solar </> ao lançar (ganhe 2 pontos de <HighLight> Energia Solar </> no estado <HighLight> Sol Ardente </>). \n Esta habilidade pode ser carregada 2 vezes. \n\n <FaintYellow> Energia Solar </>: Mantenha até 5 pontos. Obtenha Energia Solar para desbloquear e fortalecer <HighLight> Punição </> e <HighLight> Lança Sem Sombra </>.",
  [285943353322496] = "Estabeleça um Juramento Solar no local designado com duração de 8 segundos, causando dano físico de Spellfielddisc(*id) aos inimigos dentro da área e aplicando <HyperLink stylename=\"M_Link\" u=\"9\"> Estagnação </> contínua. Posteriormente, acione <HighLight> Escaldante </> uma vez a cada 0,5 segundos. Inimigos dentro do alcance do juramento são afetados por trapdisc(*id) (há um limite para o número de gatilhos). \nGanhe 2 pontos de <HighLight> Energia Solar </> ao lançar (ganhe 3 pontos de <HighLight> Energia Solar </> enquanto estiver no estado <HighLight> Sol Ardente </>) e, posteriormente, ganhe 1 ponto de <HighLight> Energia Solar </> a cada 2 segundos enquanto permanecer dentro do alcance do juramento. \n\n <FaintYellow> Abrasador </> : Inimigos dentro do alcance do juramento sofrem dano físico de Spellfielddisc(*id), e o dano subsequente do <HighLight> Abrasador </> desta habilidade é aumentado em 15% (até um máximo de 150%). \n <FaintYellow> Energia Solar </> : Segure até 5 pontos; obtenha Energia Solar para desbloquear e fortalecer <HighLight> Punição </> e <HighLight> Lança Sem Sombra </>.",
  [285943353322240] = "Atordoa os inimigos próximos.",
  [285943353320960] = "Condensa um machado curto para atacar continuamente os inimigos ao redor por 6 segundos, causando *d dano físico a cada 0,8 segundos e *f segundos de mul(*d**,*d) <HyperLink stylename=\"M_Link\" u=\"20\"> Redução de Cura </> , com uma probabilidade básica de *f** de aplicar Estagnação por *f segundos; \n ganha 1 ponto de <HighLight> Energia Solar </> ao lançar (ganha 2 pontos de <HighLight> Energia Solar </> no estado <HighLight> Sol Ardente </>), depois ganha 1 ponto de <HighLight> Energia Solar </> a cada 2 ataques. \n\n <FaintYellow> Energia Solar </>: Mantenha até 5 pontos. Obtenha Energia Solar para desbloquear e fortalecer <HighLight> Punição </> e <HighLight> Lança Sem Sombra </>.",
  [285943353320704] = "Avança para cortar, causando dano físico de Spellfielddisc(*id) ao alvo e aos inimigos em uma pequena área ao redor dele, e <HyperLink stylename=\"M_Link\" u=\"21\"> purifica </> inimigos em um estado dissipado. Ganhe 1 ponto de <HighLight> Energia Solar </> (ganhe 2 pontos de <HighLight> Energia Solar </> no estado <HighLight> Sol Ardente </>). \n\n <FaintYellow> Energia Solar </>: Mantenha até 5 pontos. Obtenha Energia Solar para desbloquear e fortalecer <HighLight> Punição </> e <HighLight> Lança Sem Sombra </>.",
  [285943353320448] = "No estado <HighLight> Sol Ardente </>, você saltará na frente do inimigo e então atacará com força total, causando 1 instância de *d dano físico e <HyperLink stylename=\"M_Link\" u=\"2\"> derrubando </> monstros inimigos, e ganhando 1 ponto de <HighLight> Energia Solar </> ao acertar.",
  [285943353319680] = "Executa um golpe de três estágios nos inimigos em uma pequena área à frente, causando *d, *d+*d e *d de dano físico respectivamente e repelindo levemente <HyperLink stylename=\"M_Link\" u=\"2\"> monstros inimigos; ganhe 1 ponto de <HighLight> Energia Solar </> após atingir o terceiro estágio. \nskilldisc(*id)\n\n <FaintYellow> Energia Solar </> : Mantenha até 5 pontos. Obtenha Energia Solar para desbloquear e fortalecer <HighLight> Punição </> e <HighLight> Lança Sem Sombra </>.</>",
  [285943353318400] = "Transforma-se em uma criatura inofensiva e imediatamente entra em um estado de morte fingida por 30 segundos. Todos os inimigos não irão adicionar você à sua lista de ódio, mas qualquer ataque ativo encerrará este estado.",
  [285943353318144] = "Dentro de 30 segundos, permite montar em combate e causa dano aos alvos colididos. Monta automaticamente ao usar habilidades.",
  [285943353316864] = "Transforma-se em Sol Ardente em combate por 15 segundos, ganhando 90% de redução de dano e causando alto dano aos inimigos queimados. Não é possível atacar, pular ou esquivar durante este período.",
  [285943353316608] = "Imobiliza permanentemente todos os inimigos normais em um raio de 40 metros. Só pode ser lançado uma vez por camada.",
  [285943353315072] = "【Modo do controle direito 1】 Causa vários tipos de dano com efeitos diferentes a todos os inimigos dentro do alcance selecionado.",
  [285943353314816] = "Se o alvo estiver a uma distância de 2.000, atira uma bala nele. Pode ter seu backswing cancelado por certas habilidades.",
  [285943353314560] = "[Modo 3 do controle direito] Uma combinação da habilidade do Modelo 7, distribuindo efeitos em uma área em forma de leque na frente, com você mesmo como centro, e repelindo.",
  [285943353314304] = "[Modo do controle direito 3] Causa efeitos em uma área em forma de leque na frente, com você mesmo como centro. Pode liberar habilidades combinadas; entra em recarga depois que o combo terminar.",
  [285943353314048] = "[Modo 4 do controle direito] Ataca os inimigos dentro de um alcance retangular à frente. Observe que os parâmetros de comprimento e largura da filtragem alvo estão relacionados aos parâmetros de aviso do modo de controle direito.",
  [285943353313792] = "[Modo 7 do controle direito] Ataca os inimigos em um alcance circular à frente. Observe que os parâmetros de deslocamento e raio da filtragem do alvo estão relacionados aos parâmetros de aviso do modo de controle direito.",
  [285943353313536] = "Causa dano A ao alvo bloqueado e libera um campo de feitiço em seu local.",
  [285943353313024] = "Causa dano A e aplica um buff ao alvo travado, e causa dano B a alvos em um raio de 5 metros dele.",
  [285943353312768] = "Obtenha o resultado do cálculo da fórmula de habilidade: *d\n Obtenha esta habilidade CA parâmetro nomeado:*.2f\n Obtenha esta habilidade CA parâmetro sem nome:*f**\n Obtenha outra configuração de habilidade nesta tabela:*s\n Obtenha a descrição do agente de feitiço: Spellagent(*id)\n Obtenha o nome da habilidade: skillname(*id)\n Obtenha a descrição da habilidade: skilldisc(*id)\n Obtenha o nome do Buff: buffname(*id)\n Obtenha a descrição do buff: buffdisc(*id)\n Obtenha o nome do campo de feitiço: Spellfieldname(*id)\n Obtenha a descrição do campo de feitiço: Spellfielddisc(*id)\n Obtenha o nome da aura: auraname(*id)\n Obtenha a descrição da aura: auradisc(*id)\n Obtenha o nome passivo: passivaname(*id)\n Obtenha a descrição passiva: passivadisc(*id)\n Obtenha o nome da armadilha: trapname(*id)\n Obtenha a descrição da armadilha: trapdisc(*id)",
